const infectedFit = (group: string): PersonaCategoryFit => {
  if (group.startsWith('A.')) return personaFit('weak', {
    strong: ['medical', 'horror', 'body_horror', 'biopunk'],
    usable: ['science_fiction', 'post_apocalyptic', 'urban_life'],
    fusion: ['romance', 'dark_fantasy'],
    weak: ['court', 'wuxia', 'xianxia']
  });
  if (group.startsWith('B.')) return personaFit('weak', {
    strong: ['biopunk', 'body_horror', 'horror'],
    usable: ['medical', 'science_fiction', 'romance'],
    fusion: ['dark_fantasy', 'surreal'],
    weak: ['court', 'wuxia', 'historical']
  });
  if (group.startsWith('C.')) return personaFit('weak', {
    strong: ['science_fiction', 'medical', 'biopunk'],
    usable: ['cyberpunk', 'posthuman', 'noir_crime'],
    fusion: ['body_horror', 'horror'],
    weak: ['court', 'historical', 'xianxia']
  });
  if (group.startsWith('D.')) return personaFit('weak', {
    strong: ['biopunk', 'body_horror', 'science_fiction'],
    usable: ['posthuman', 'fantasy', 'horror'],
    fusion: ['xianxia', 'dark_fantasy'],
    weak: ['real_professional', 'court', 'romance']
  });
  if (group.startsWith('E.')) return personaFit('weak', {
    strong: ['medical', 'biopunk', 'posthuman'],
    usable: ['science_fiction', 'body_horror', 'fashion_idol'],
    fusion: ['boudoir_aesthetic', 'surreal'],
    weak: ['wuxia', 'court', 'mythic_epic']
  });
  if (group.startsWith('F.')) return personaFit('weak', {
    strong: ['biopunk', 'science_fiction', 'posthuman'],
    usable: ['medical', 'body_horror', 'cyberpunk'],
    fusion: ['surreal', 'cosmic_horror'],
    weak: ['court', 'historical', 'wuxia']
  });
  if (group.startsWith('G.')) return personaFit('weak', {
    strong: ['body_horror', 'horror', 'biopunk'],
    usable: ['science_fiction', 'medical', 'post_apocalyptic'],
    fusion: ['dark_fantasy', 'surreal'],
    weak: ['romance', 'court', 'workplace']
  });
  if (group.startsWith('H.')) return personaFit('weak', {
    strong: ['science_fiction', 'posthuman', 'biopunk'],
    usable: ['medical', 'cyberpunk', 'institutional'],
    fusion: ['body_horror', 'surreal'],
    weak: ['historical', 'court', 'wuxia']
  });
  if (group.startsWith('I.')) return personaFit('weak', {
    strong: ['ecological', 'biopunk', 'body_horror'],
    usable: ['horror', 'post_apocalyptic', 'medical'],
    fusion: ['fantasy', 'dark_fantasy', 'xianxia'],
    weak: ['court', 'workplace', 'fashion_idol']
  });
  return personaFit('weak', {
    strong: ['medical', 'noir_crime', 'biopunk'],
    usable: ['body_horror', 'science_fiction', 'urban_life'],
    fusion: ['dark_fantasy', 'romance'],
    weak: ['court', 'xianxia', 'mythic_epic']
  });
};

