const ip = (seed: PersonaSeed): PersonaTerm => {
  const ontologyLevel = seed.ontologyLevel ?? 4;
  const eras = cleanPersonaEras(seed.eras ?? modernBio);
  const risk = seed.risk ?? (ontologyLevel >= 4 ? 'high' : 'medium');
  const controls = Array.from(new Set([...baseControls, ...(seed.controls || [])]));
  const eraMode = personaEraModeFor(eras, seed.eraMode);
  return {
    id: `cd_persona_infected_experiment_${seed.id}`,
    name: seed.name,
    nameEn: seed.nameEn,
    group: seed.group,
    groupEn: seed.groupEn,
    def: seed.def,
    defEn: seed.defEn,
    personaCategory: '感染 / 寄生 / 实验体人设',
    personaCategoryEn: 'Infection / Parasite / Experiment Subject Persona',
    personaSubgroup: seed.group.replace(/^[A-J]\.\s*/, ''),
    personaSubgroupEn: seed.groupEn.replace(/^[A-J]\.\s*/, ''),
    personaKind: seed.name,
    personaKindEn: seed.nameEn,
    personaStrength: ontologyLevel >= 4 ? 'strong' : ontologyLevel >= 2 ? 'medium' : 'light',
    isCompoundPersona: true,
    ontologyLevel,
    eraMode,
    eras,
    risk,
    affects: controls,
    controls,
    forbids: Array.from(new Set([...(seed.forbids || []), ...defaultForbids])),
    absorptionRule: seed.absorptionRule || `外来元素优先折译为“${seed.name}”的血肉边界、感染来源、实验编号、医疗流程、寄生关系、隔离制度或失控身体，不要直接堆成无关奇观。`,
    absorptionRuleEn: seed.absorptionRuleEn || `Translate outside elements into the flesh boundary, infection source, experiment code, medical workflow, parasitic relation, quarantine system, or runaway body of "${seed.nameEn}"; do not stack them into unrelated spectacle.`,
    tags: Array.from(new Set(['persona', 'infection', 'parasite', 'experiment', 'compound_persona', ...(seed.tags || [])])),
    realityTags: seed.realityTags || personaRealityTagsFor(ontologyLevel, ['infection', 'medical']),
    categoryFit: seed.categoryFit || infectedFitOverrides[seed.id] || infectedFit(seed.group),
    styleTags: Array.from(new Set(['biohorror', 'experiment_subject', ...(seed.styleTags || []), ...(seed.tags || [])])),
    timeTags: eras
  };
};

const seeds: PersonaSeed[] = [
  { id: 'infected_test_subject', name: '感染实验体', nameEn: 'Infected Test Subject', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是从感染试验里被保留下来的活体样本。造型入口：病号服、红色腕带、皮肤下扩散的斑纹、被抽血后的胶布和像不确定自己是否还能被触碰的站姿。母题：身体既是病人也是证据。张力：不要只做怪物化，重点是实验编号、发热呼吸和被观察的羞耻。视觉证据：采样管、隔离玻璃、皮肤潮红、手臂针孔、躲避医护手套的眼神。边界：避免普通病人或丧尸化。', defEn: 'First read: a living specimen preserved from an infection trial. Styling entry: patient gown, red wristband, spreading subdermal marks, post-blood-draw tape, and a stance unsure whether the body can still be touched. Motif: the body is both patient and evidence. Tension: do not make it just monsterized; focus on experiment number, fever breathing, and the shame of being observed. Visual evidence: sample tubes, isolation glass, flushed skin, needle marks, and eyes avoiding medical gloves. Boundary: avoid a generic patient or zombie turn.', tags: ['infected', 'test_subject'] },
  { id: 'quarantine_schoolgirl', name: '隔离女学生', nameEn: 'Quarantine Schoolgirl', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是校服还在身上、生活却被隔离制度截断的女学生。造型入口：旧书包、透明面罩、校服袖口消毒斑、体温贴和站在黄色隔离线后的身体。母题：青春日常被公共卫生流程突然接管。张力：她不是普通校园角色，恐惧来自仍想上课却被当成风险源。视觉证据：作业本、隔离通知、口罩压痕、眼下疲惫、握紧书包带的手。边界：避免可爱化隔离或普通校服写真。', defEn: 'First read: a schoolgirl whose uniform remains while life is cut off by quarantine. Styling entry: old schoolbag, clear face shield, disinfectant stains on cuffs, temperature sticker, and a body behind yellow isolation tape. Motif: youth routine suddenly taken over by public-health procedure. Tension: she is not a generic school character; fear comes from wanting class while being treated as a risk source. Visual evidence: homework, quarantine notice, mask marks, tired under-eyes, and hands gripping bag straps. Boundary: avoid cute quarantine styling or ordinary school portrait.', risk: 'medium', tags: ['quarantine', 'schoolgirl'] },
  { id: 'plague_survivor_boy', name: '瘟疫幸存少年', nameEn: 'Plague Survivor Boy', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是从瘟疫区里活下来、身体和衣物都留下筛查痕迹的少年。造型入口：褪色外套、颈侧检查印、干裂嘴唇、过大的求生包和比年龄更警惕的眼神。母题：幸存不是胜利，而是带着证明自己无害的负担继续走。张力：他不该像英雄，应该像被排队、消毒和驱赶塑成的人。视觉证据：健康通行贴、旧水壶、药纸、手背疤痕、避开人群的站位。边界：避免普通流浪少年或末日主角爽感。', defEn: 'First read: a boy who survived the plague zone, with screening traces on body and clothing. Styling entry: faded coat, neck-side inspection stamp, cracked lips, oversized survival bag, and eyes more alert than his age. Motif: survival is not victory but the burden of proving harmlessness. Tension: he should not look heroic; he should look shaped by lines, sterilization, and rejection. Visual evidence: health pass stickers, old canteen, medicine papers, hand scars, and standing away from crowds. Boundary: avoid generic stray boy or apocalypse hero fantasy.', risk: 'medium', tags: ['plague', 'survivor', 'boy'] },
  { id: 'viral_bride', name: '病毒新娘', nameEn: 'Viral Bride', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是婚礼仪式与病毒隔离同时发生的新娘。造型入口：白纱、防护手套、隔离编号、花束外的透明袋和不敢被亲吻的侧脸。母题：亲密承诺被传染风险切开。张力：她不是病弱新娘，而是婚礼中心突然变成全场风险中心。视觉证据：婚戒隔着手套、消毒灯、白裙上的封条、口罩压出的妆痕。边界：避免普通婚纱照或廉价病毒怪谈。', defEn: 'First read: a bride whose wedding ritual and viral quarantine happen at once. Styling entry: white veil, protective gloves, isolation number, bouquet inside clear cover, and a profile afraid to be kissed. Motif: intimate promise cut open by contagion risk. Tension: she is not a fragile bride; the wedding center has become the risk center of the room. Visual evidence: ring over gloves, sterilizing light, seals on white dress, and makeup marked by a mask. Boundary: avoid generic bridal portrait or cheap virus horror.', risk: 'high', tags: ['viral', 'bride', 'wedding'] },
  { id: 'fever_dream_patient', name: '热病梦患者', nameEn: 'Fever-Dream Patient', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是高热让现实边界松动的病人。造型入口：湿发、贴在额头的冷敷布、皱床单、半睁眼和像在看见房间以外东西的手势。母题：病变通过梦境改变观看关系。张力：不要变成抽象幻觉，要保留病床、体温和身体虚弱的锚点。视觉证据：体温计、汗湿领口、药杯、凌乱呼吸、抓住床沿的手。边界：避免普通发烧病人或纯梦境美术。', defEn: 'First read: a patient whose fever loosens reality boundaries. Styling entry: wet hair, cold cloth on forehead, wrinkled sheets, half-open eyes, and a hand gesture seeing beyond the room. Motif: pathology alters viewing relation through dream. Tension: do not become abstract hallucination; keep bed, temperature, and bodily weakness as anchors. Visual evidence: thermometer, sweaty collar, medicine cup, uneven breathing, and hands gripping bed edge. Boundary: avoid generic fever patient or pure dream art.', tags: ['fever', 'patient', 'dream'] },
  { id: 'contagion_nurse', name: '传染病护士', nameEn: 'Contagion Nurse', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', ontologyLevel: 3, def: '第一识别是长期在传染病区里工作、身体也被防护流程塑形的护士。造型入口：护目镜勒痕、双层手套、消毒喷雾、写满病号的夹板和不敢揉眼的疲惫。母题：照护者也被隔离制度消耗。张力：她不是圣洁护士，专业性来自重复、谨慎和被污染风险包围。视觉证据：面罩雾气、手套粉、隔离服褶皱、贴在胸前的姓名条。边界：避免普通护士或神圣化医疗英雄。', defEn: 'First read: a nurse shaped by long work inside contagion wards and protective procedure. Styling entry: goggle marks, double gloves, disinfectant spray, clipboard full of patients, and fatigue that cannot rub the eyes. Motif: the caregiver is also consumed by quarantine order. Tension: she is not a holy nurse; professionalism comes from repetition, caution, and contamination risk. Visual evidence: fogged shield, glove powder, creased isolation suit, and name tape on chest. Boundary: avoid generic nurse or sanctified medical hero.', risk: 'medium', tags: ['nurse', 'contagion', 'ward'] },
  { id: 'isolation_ward_child', name: '隔离病房儿童', nameEn: 'Isolation-Ward Child', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是儿童身体被隔离病房的玻璃、玩具和规则围住。造型入口：小号病号服、塑料玩具、窗边手印、腕带和隔着玻璃向外看的安静脸。母题：童年被无菌空间替代。张力：保持非猎奇，重点是空间隔离、亲密缺席和被迫安静。视觉证据：小床、画纸、透明隔板、护士贴纸、不能被抱起的距离。边界：避免恐怖儿童或卖惨病童照。', defEn: 'First read: a child body enclosed by ward glass, toys, and rules. Styling entry: small patient gown, plastic toy, handprints on window, wristband, and a quiet face looking through glass. Motif: childhood replaced by sterile space. Tension: keep non-spectacular; focus on spatial isolation, absent intimacy, and forced quietness. Visual evidence: small bed, drawings, clear partition, nurse stickers, and distance that cannot be hugged across. Boundary: avoid horror child or pity-photo patient.', risk: 'medium', tags: ['child', 'isolation_ward'] },
  { id: 'skin_rash_model', name: '皮疹模特', nameEn: 'Skin-Rash Model', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是皮疹、时装镜头和身体展示发生冲突的模特。造型入口：裸露肩颈、淡红斑点、遮瑕边缘、摄影棚灯和仍然按职业要求保持线条的姿态。母题：商业观看无法完全抹掉病变表面。张力：不要把皮疹当丑化，要让它成为皮肤真实和镜头控制之间的证据。视觉证据：粉底裂开、红斑、冷光、细肩带、忍住抓挠的手。边界：避免普通美妆模特或病变猎奇。', defEn: 'First read: a model where rash, fashion camera, and body display conflict. Styling entry: exposed neck and shoulders, pale red patches, concealer edges, studio light, and a professional line held despite discomfort. Motif: commercial viewing cannot fully erase pathological surface. Tension: do not use rash as uglification; make it evidence between skin reality and camera control. Visual evidence: cracked foundation, red patches, cold light, thin straps, and a hand resisting scratching. Boundary: avoid generic beauty model or disease spectacle.', risk: 'medium', tags: ['rash', 'model', 'skin'] },
  { id: 'mask_mark_worker', name: '口罩压痕工人', nameEn: 'Mask-Mark Worker', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', ontologyLevel: 2, def: '第一识别是脸上长期留下口罩压痕的普通工人。造型入口：压红的鼻梁、耳后勒痕、工牌、防护口罩挂在下巴和刚下班仍没恢复的呼吸。母题：防护变成劳动痕迹。张力：他不需要非现实病变，现实疲惫已经足够说明制度压力。视觉证据：安全帽、湿口罩、灰尘衣领、午餐盒、低头揉耳朵的手。边界：避免普通口罩自拍或末日感染者。', defEn: 'First read: an ordinary worker whose face carries long-term mask pressure marks. Styling entry: reddened nose bridge, ear strap marks, work badge, mask hanging under chin, and breathing not yet recovered after shift. Motif: protection becomes labor trace. Tension: no nonreal disease needed; realistic fatigue already shows institutional pressure. Visual evidence: hard hat, damp mask, dusty collar, lunchbox, and a hand rubbing the ear. Boundary: avoid generic mask selfie or apocalypse infected.', risk: 'clean', tags: ['mask_mark', 'worker', 'realist'] },
  { id: 'red_tag_patient', name: '红标患者', nameEn: 'Red-Tag Patient', group: 'A. 感染 / 病变 / 隔离对象', groupEn: 'A. Infection / Pathology / Quarantine Subject', def: '第一识别是被红色标签划入高风险通道的患者。造型入口：胸前红标、临时病床、被单上的编号、等待转运的侧坐和不敢询问结果的表情。母题：一个颜色改变身体的社会位置。张力：他不是普通病人，红标让所有目光、距离和流程都发生变化。视觉证据：分诊牌、塑料腕带、红色贴纸、推床轮子、僵住的手指。边界：避免泛泛医疗场景。', defEn: 'First read: a patient routed into high-risk procedure by a red tag. Styling entry: red chest tag, temporary bed, number on sheet, side-sitting while waiting for transfer, and an expression afraid to ask results. Motif: one color changes the social position of the body. Tension: not a generic patient; the red tag alters every gaze, distance, and workflow. Visual evidence: triage sign, plastic wristband, red sticker, stretcher wheels, and frozen fingers. Boundary: avoid a vague medical scene.', tags: ['red_tag', 'patient', 'triage'] },

  { id: 'parasite_host_girl', name: '寄生宿主少女', nameEn: 'Parasite-Host Girl', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是体内寄生物已经影响姿态、眼神和服装边界的年轻女性。造型入口：腹侧轻微鼓起、束带保护区、衣料被顶出的弧线和像在听体内声音的偏头。母题：宿主身份不是被占领完毕，而是在协商中摇晃。张力：寄生感必须来自依赖和不安，不是单纯虫子钻出来。视觉证据：皮肤下阴影、保护性抱臂、细管状纹路、避开触碰的后退。边界：避免普通怪物女孩或性感寄生设定。', defEn: 'First read: a young woman whose internal parasite already affects posture, gaze, and clothing boundary. Styling entry: slight side-abdominal swelling, protective straps, fabric pushed into curves, and a head tilt listening to an inner voice. Motif: host identity is not fully possessed; it wavers in negotiation. Tension: parasitic feeling must come from dependence and unease, not simply a bug emerging. Visual evidence: subdermal shadows, protective folded arms, fine tubular patterns, and stepping back from touch. Boundary: avoid generic monster girl or sexualized parasite setup.', tags: ['parasite', 'host'] },
  { id: 'symbiotic_boyfriend', name: '共生男友', nameEn: 'Symbiotic Boyfriend', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是亲密关系和共生关系重叠的男友形象。造型入口：共享呼吸器、胸口贴合痕、温柔手势里藏着依赖性、外套内侧有活体接口。母题：爱与生物依赖难以分开。张力：他不是普通恋人，关心动作同时像维持宿主系统。视觉证据：两人距离标记、体温读数、皮肤连接点、过度注意对方状态的眼神。边界：避免纯恋爱男主或恐怖附身。', defEn: 'First read: a boyfriend figure where intimacy and symbiosis overlap. Styling entry: shared breather, chest contact marks, tenderness hiding dependence, and living ports inside the jacket. Motif: love and biological reliance become hard to separate. Tension: he is not a generic lover; caring gestures also maintain a host system. Visual evidence: distance markers, temperature readout, skin connection points, and eyes overly tracking the other body. Boundary: avoid pure romance lead or horror possession.', tags: ['symbiosis', 'boyfriend', 'intimacy'] },
  { id: 'chest_flower_host', name: '胸口开花宿主', nameEn: 'Chest-Flower Host', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是胸腔位置被寄生花朵顶开、仍保持人形礼仪的宿主。造型入口：敞开的衣领、花茎从胸口支撑出来、手掌护住花冠、呼吸被花瓣节奏打断。母题：美丽从伤口位置生长。张力：花不能只是装饰，它必须改变呼吸、姿态和被观看的羞耻。视觉证据：胸口支撑线、渗液、花粉、苍白锁骨、压低肩膀。边界：避免普通花仙子或唯美花胸装。', defEn: 'First read: a host whose chest is opened by parasitic flowers while still holding human etiquette. Styling entry: open collar, stems supporting from the chest, palms protecting the blossom, and breathing interrupted by petal rhythm. Motif: beauty grows from the wound position. Tension: the flower cannot be decoration; it must alter breath, posture, and shame under view. Visual evidence: chest support lines, secretion, pollen, pale collarbones, and lowered shoulders. Boundary: avoid generic flower fairy or pretty floral bodice.', tags: ['flower_host', 'parasite'] },
  { id: 'worm_eye_oracle', name: '虫眼预言者', nameEn: 'Worm-Eye Oracle', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是眼部寄生虫让预言能力和视觉损伤同时成立的人。造型入口：覆眼纱、虹膜里细小蠕动、手持记录板、说话前像等待虫体转向的停顿。母题：预言不是神赐，而是被寄生视觉读取。张力：神秘感要落在眼睛的脆弱和不适，而不是华丽法术。视觉证据：眼罩、泪痕、微小虫影、旁人不敢直视的距离。边界：避免普通先知或恶心虫堆。', defEn: 'First read: an oracle whose eye parasites create prophecy and visual damage at once. Styling entry: eye veil, tiny movement in the iris, record board, and pauses before speech as if waiting for the worm to turn. Motif: prophecy is not divine gift but parasitic sight. Tension: mystery should land in eye fragility and discomfort, not ornate magic. Visual evidence: eye cover, tear tracks, small worm shadows, and people avoiding direct gaze. Boundary: avoid generic prophet or gross worm pile.', tags: ['worm_eye', 'oracle'] },
  { id: 'parasite_bride', name: '寄生新娘', nameEn: 'Parasite Bride', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是婚礼身体已经与寄生物签订另一种亲密关系的新娘。造型入口：婚纱下若隐若现的生物纹路、束腰变成固定宿主的结构、花束像饲养器。母题：婚姻承诺被第三个生命体介入。张力：她不是被污染的新娘，而是在两个关系系统之间维持礼仪。视觉证据：白纱里的暗色脉络、手套下凸起、戒指和宿主标记并置。边界：避免普通怪谈新娘或寄生恋物化。', defEn: 'First read: a bride whose wedding body has entered another intimacy with a parasite. Styling entry: biological patterns under gown, corset turning into host fixture, and bouquet reading like a feeder. Motif: marriage promise interrupted by a third life form. Tension: she is not a polluted bride; she maintains etiquette between two relation systems. Visual evidence: dark veins under white veil, raised forms under gloves, and ring beside host mark. Boundary: avoid generic horror bride or fetishized parasite.', tags: ['parasite', 'bride'] },
  { id: 'hive_voice_mother', name: '蜂巢声音母亲', nameEn: 'Hive-Voice Mother', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是说话时像有多个声音从同一喉咙里排队出来的母亲。造型入口：喉部蜂巢纹、家居围裙、保护孩子的身体位置和每次发声前的集体嗡鸣感。母题：母职被群体生物接管又继续照护。张力：她不是邪恶母体，恐惧来自温柔声音里藏着许多意志。视觉证据：喉部纹路、耳边细响、孩子躲在身后、过度同步的眼神。边界：避免普通蜂后或恐怖母亲套路。', defEn: 'First read: a mother whose speech sounds like many voices queuing through one throat. Styling entry: hive marks at the throat, home apron, protective placement before children, and a collective hum before every word. Motif: motherhood taken over by group organism yet still caring. Tension: she is not an evil mother; unease comes from tenderness carrying many wills. Visual evidence: throat pattern, fine buzzing near ears, child behind her, and overly synchronized eyes. Boundary: avoid generic bee queen or horror mother trope.', tags: ['hive_voice', 'mother'] },
  { id: 'leech_doctor_patient', name: '水蛭医生患者', nameEn: 'Leech Doctor Patient', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是医生和患者身份被水蛭疗法、身体债务和血液管理缠在一起的人。造型入口：白袍下的病号袖、玻璃罐、水蛭痕、止血布和一边治疗一边被治疗的手势。母题：医疗权力反向寄生在身体上。张力：他不是古怪医生，关键是专业、贫穷和被迫交换血液。视觉证据：水蛭罐、账本、手臂圆形咬痕、疲惫但准确的手。边界：避免滑稽旧医学或纯恶心画面。', defEn: 'First read: a person where doctor and patient roles are tangled by leech therapy, body debt, and blood management. Styling entry: patient sleeves under a white coat, glass jars, leech marks, gauze, and gestures treating while being treated. Motif: medical power parasitizes the body in reverse. Tension: not a quirky doctor; the key is professionalism, poverty, and forced blood exchange. Visual evidence: leech jars, ledger, circular arm bites, and tired but precise hands. Boundary: avoid comic old medicine or pure gross-out image.', tags: ['leech', 'doctor_patient'] },
  { id: 'back_spine_symbiote', name: '背脊共生体', nameEn: 'Back-Spine Symbiote', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是背脊上附着的共生体改变了人的站姿和衣服开合。造型入口：背部开窗衣料、沿脊柱起伏的活体结构、肩胛保护带和不愿靠墙的身体习惯。母题：身体后方成为第二个生命的正面。张力：共生体不能只是背饰，它必须改变平衡、睡眠和社交距离。视觉证据：背脊凸起、固定扣、局部潮湿、回头警惕的眼神。边界：避免普通背刺怪物或装饰性脊甲。', defEn: 'First read: a spine-attached symbiote changing posture and clothing openings. Styling entry: back-window garments, living structure rising along the spine, scapula straps, and a habit of never leaning against walls. Motif: the back becomes the front of a second life. Tension: the symbiote cannot be a back ornament; it must alter balance, sleep, and social distance. Visual evidence: spine bulges, fixing clasps, local moisture, and wary eyes looking back. Boundary: avoid generic back-spike monster or decorative spine armor.', tags: ['spine_symbiote', 'back'] },
  { id: 'alien_larva_courier', name: '异星幼虫信使', nameEn: 'Alien-Larva Courier', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', ontologyLevel: 5, eras: future, def: '第一识别是体内携带异星幼虫、把自己也变成运输容器的信使。造型入口：保温腹带、星际通行封签、轻微发光的皮下阴影、赶路时保护腹部的手。母题：物流、繁殖和牺牲混在一个身体里。张力：他不是普通外星怪物，危险来自任务必须准时到达。视觉证据：运输编号、生命读数、汗水、腹部护壳、警觉路线图。边界：避免纯异形恐怖或普通快递员。', defEn: 'First read: a courier carrying alien larvae inside the body, becoming the container too. Styling entry: thermal belly harness, interstellar transit seal, faintly glowing subdermal shadow, and a hand protecting the abdomen while moving. Motif: logistics, reproduction, and sacrifice inside one body. Tension: not a generic alien monster; danger comes from the mission needing to arrive on time. Visual evidence: transport number, life readout, sweat, abdominal guard, and alert route map. Boundary: avoid pure xenomorph horror or a normal courier.', tags: ['alien_larva', 'courier'] },
  { id: 'parasite_contract_lawyer', name: '寄生契约律师', nameEn: 'Parasite-Contract Lawyer', group: 'B. 寄生 / 共生 / 宿主', groupEn: 'B. Parasite / Symbiosis / Host', def: '第一识别是专门处理宿主权利、寄生期限和共生赔偿的律师。造型入口：深色西装、皮肤下微弱蠕动、合同夹、无菌手套和把怪异关系说得极其合法的表情。母题：寄生关系被制度化。张力：他不需要恐怖外形，真正危险是能把占有写成条款。视觉证据：合同页、签字笔、宿主图示、领口下的生物纹路。边界：避免普通律师或邪恶科学家。', defEn: 'First read: a lawyer specializing in host rights, parasite duration, and symbiosis compensation. Styling entry: dark suit, faint subdermal movement, contract folder, sterile gloves, and an expression making bizarre relations sound legal. Motif: parasitic relation institutionalized. Tension: no horror exterior needed; the real danger is turning possession into clauses. Visual evidence: contract pages, pen, host diagrams, and biological lines under collar. Boundary: avoid generic lawyer or evil scientist.', tags: ['parasite_contract', 'lawyer'] },

  { id: 'lab_escape_subject_07', name: '七号逃亡实验体', nameEn: 'Lab Escape Subject 07', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', def: '第一识别是刚从实验室逃出来、编号仍比姓名更醒目的七号个体。造型入口：撕开的拘束服、腕部束缚痕、胸前编号、赤脚或临时拖鞋和贴墙移动的警觉。母题：身份从档案编号里挣脱但还没获得自由。张力：逃亡感要靠身体习惯和实验痕迹，不是动作片追逐。视觉证据：门禁卡、血样贴、监控盲区、喘息和回头确认的肩线。边界：避免普通病号逃跑或英雄越狱。', defEn: 'First read: Subject 07 freshly escaped from a lab, with the number still louder than any name. Styling entry: torn restraint gown, wrist binding marks, chest code, bare feet or temporary slippers, and wall-hugging alert movement. Motif: identity breaking from file number before finding freedom. Tension: escape should read through bodily habit and experiment traces, not action-movie chase. Visual evidence: keycard, blood-sample label, blind camera corner, breath, and a shoulder line checking behind. Boundary: avoid a generic patient escape or heroic jailbreak.', tags: ['lab_escape', 'numbered_subject'] },
  { id: 'white_room_child', name: '白房间儿童', nameEn: 'White-Room Child', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', risk: 'medium', def: '第一识别是被白色观察房养大的儿童，干净到近乎没有日常生活痕迹。造型入口：过白衣物、软墙角、测试积木、编号手环和不知道如何站在真实世界里的脚。母题：无菌环境替代了童年。张力：不要恐怖儿童化，重点是空白、训练和对普通物件的陌生。视觉证据：观察窗、记录表、握得太紧的玩具、平静但缺少社交反馈的眼神。边界：避免卖惨病童或鬼童。', defEn: 'First read: a child raised inside a white observation room, too clean to carry ordinary life traces. Styling entry: over-white clothes, padded wall corners, testing blocks, number bracelet, and feet unsure how to stand in the real world. Motif: sterile environment replacing childhood. Tension: avoid horror-child coding; focus on blankness, training, and unfamiliarity with ordinary objects. Visual evidence: observation window, record sheets, toy gripped too tightly, and calm eyes lacking social feedback. Boundary: avoid pity patient child or ghost child.', tags: ['white_room', 'child'] },
  { id: 'tank_grown_girl', name: '培养舱女孩', nameEn: 'Tank-Grown Girl', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', ontologyLevel: 4, def: '第一识别是从培养舱里长成、仍带着液体环境痕迹的年轻女性。造型入口：湿发、透明导管印、薄膜披覆、脚步不稳和像第一次承受空气重量的呼吸。母题：身体被制造出来，却还没学会社会姿态。张力：不要水族馆式美化，重点是诞生设备、皮肤脆弱和对触碰的迟疑。视觉证据：培养液残光、舱号、皮肤皱白、扶墙站立。边界：避免普通人鱼或科幻睡美人。', defEn: 'First read: a young woman grown in a tank, still carrying traces of liquid environment. Styling entry: wet hair, transparent tube marks, membrane drape, unstable steps, and breathing as if air has weight for the first time. Motif: a body manufactured before learning social posture. Tension: avoid aquarium prettiness; focus on birth equipment, fragile skin, and hesitation toward touch. Visual evidence: culture-fluid shine, tank number, wrinkled pale skin, and standing with wall support. Boundary: avoid mermaid imagery or sci-fi sleeping beauty.', tags: ['tank_grown', 'girl'] },
  { id: 'barcode_neck_boy', name: '颈部条码少年', nameEn: 'Barcode-Neck Boy', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', def: '第一识别是颈侧条码把他从人变成可扫描资产的少年。造型入口：短发露出后颈、扫码伤痕、旧连帽衫、躲避闸机的低头姿态。母题：身份被读取技术压在皮肤上。张力：他不是普通街头少年，所有紧张都来自“被扫到就会被找回”。视觉证据：条码刺青、擦不掉的胶痕、门禁红光、手遮后颈。边界：避免普通纹身少年或赛博酷炫标签。', defEn: 'First read: a boy whose neck barcode turns him into scannable property. Styling entry: short hair exposing the nape, scan scars, old hoodie, and lowered posture avoiding gates. Motif: identity pressed onto skin by reading technology. Tension: not a generic street boy; every tension comes from being recovered if scanned. Visual evidence: barcode tattoo, adhesive marks that will not wash off, red access light, and a hand covering the neck. Boundary: avoid a normal tattooed teen or cool cyber label.', tags: ['barcode', 'boy', 'asset'] },
  { id: 'hospital_gown_runaway', name: '病号服逃亡者', nameEn: 'Hospital-Gown Runaway', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', def: '第一识别是穿着病号服逃到外部世界、还没来得及换回普通身份的人。造型入口：薄病号服、外套借穿、脚踝监测环、手臂输液痕和在街角被冷风打醒的身体。母题：医疗空间和城市街道突然重叠。张力：逃亡不是潇洒，而是暴露、寒冷和随时被认出的尴尬。视觉证据：医院腕带、拖鞋、临时包扎、霓虹下的苍白皮肤。边界：避免普通流浪者或性感病号服。', defEn: 'First read: a runaway still in hospital gown, not yet returned to ordinary identity. Styling entry: thin gown, borrowed outer coat, ankle monitor, IV marks, and a body shocked awake by street-corner cold. Motif: medical space suddenly overlapping city street. Tension: escape is not cool; it is exposure, cold, and the shame of being recognized. Visual evidence: hospital wristband, slippers, temporary bandage, pale skin under neon. Boundary: avoid generic vagrant or sexualized hospital gown.', tags: ['hospital_gown', 'runaway'] },
  { id: 'sedation_patch_princess', name: '镇静贴公主', nameEn: 'Sedation-Patch Princess', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', ontologyLevel: 3, def: '第一识别是身份被公主式装饰包裹、身体却被镇静贴管理的实验贵族。造型入口：精致裙装、颈侧药贴、过慢眨眼、侍从式编号牌和被药效拖住的优雅。母题：高贵姿态被医疗控制削弱。张力：不要写成童话公主，重点是礼仪、药物和被允许活动的范围。视觉证据：镇静贴边缘、细手套、监护读数、微微下坠的肩。边界：避免普通贵族少女或魔法公主。', defEn: 'First read: an experimental noble wrapped in princess-like decoration while the body is managed by sedation patches. Styling entry: refined dress, neck drug patch, slow blinking, attendant-like number plate, and elegance dragged by medication. Motif: noble posture weakened by medical control. Tension: not a fairy-tale princess; focus on etiquette, drugs, and permitted movement range. Visual evidence: patch edges, fine gloves, monitor readouts, and slightly sinking shoulders. Boundary: avoid generic noble girl or magic princess.', tags: ['sedation', 'princess', 'control'] },
  { id: 'observation_room_actor', name: '观察室演员', nameEn: 'Observation-Room Actor', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', def: '第一识别是在观察室里学会“表演正常”的实验对象。造型入口：普通衬衫过于整齐、单向玻璃、被训练出来的微笑和总在寻找摄像头位置的眼神。母题：人格像测试结果一样被表演出来。张力：他不是职业演员，而是把顺从、惊讶和亲切都练成生存技能。视觉证据：观察窗反光、行为评分表、坐姿过正、笑容停得太准。边界：避免娱乐圈演员或纯精神病院设定。', defEn: 'First read: a subject who learned to perform normality inside an observation room. Styling entry: ordinary shirt too neatly arranged, one-way glass, trained smile, and eyes always locating cameras. Motif: personhood performed like a test result. Tension: not a professional actor; compliance, surprise, and friendliness are survival skills. Visual evidence: observation-window reflection, behavior score sheet, overly straight sitting, and a smile stopping too precisely. Boundary: avoid entertainment actor or pure asylum trope.', tags: ['observation', 'actor', 'behavior_test'] },
  { id: 'lab_keycard_thief', name: '实验室门卡小偷', nameEn: 'Lab-Keycard Thief', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', ontologyLevel: 2, risk: 'medium', def: '第一识别是靠偷门卡在实验楼层之间活下来的小偷。造型入口：白大褂外套、假工牌、袖中门卡、安静脚步和看起来像员工却总不敢进电梯的身体。母题：制度漏洞成为求生技能。张力：不要塑造成帅气盗贼，重点是低风险动作、恐惧和对流程的熟悉。视觉证据：刷卡器红绿光、口袋里多张卡、手汗、监控死角地图。边界：避免普通黑客或职业小偷。', defEn: 'First read: a thief surviving between lab floors by stealing keycards. Styling entry: borrowed lab coat, fake badge, cards hidden in sleeve, quiet steps, and a body that looks like staff yet avoids elevators. Motif: institutional loopholes as survival craft. Tension: not a stylish thief; focus on low-risk gestures, fear, and knowledge of procedure. Visual evidence: red-green card reader light, multiple cards in pocket, sweaty hands, and blind-spot map. Boundary: avoid generic hacker or career criminal.', tags: ['keycard', 'thief', 'lab'] },
  { id: 'subject_zero_mother', name: '零号母体', nameEn: 'Subject-Zero Mother', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', ontologyLevel: 5, risk: 'high', def: '第一识别是所有样本源头都指向她、却仍保留母亲姿态的零号个体。造型入口：宽大隔离袍、腹部旧接口、样本编号项圈、护住空位的手和像记得每个失去孩子的眼神。母题：母职被实验系统改写成来源权限。张力：不要变成怪物母体，重点是温柔、身体产权和被反复提取后的空洞。视觉证据：源样本标签、旧针孔、儿童照片残片、隔离床。边界：避免恐怖女王或普通母亲。', defEn: 'First read: Subject Zero, the source behind all samples, while still holding a maternal posture. Styling entry: oversized isolation robe, old abdominal port, sample-code collar, hands protecting an empty space, and eyes remembering every lost child. Motif: motherhood rewritten into source rights by experiment system. Tension: do not turn her into a monster queen; focus on tenderness, body ownership, and emptiness after repeated extraction. Visual evidence: source-sample labels, old needle marks, torn child photo, isolation bed. Boundary: avoid horror matriarch or generic mother.', tags: ['subject_zero', 'mother', 'source'] },
  { id: 'containment_break_survivor', name: '收容破裂幸存者', nameEn: 'Containment-Break Survivor', group: 'C. 实验室逃亡 / 编号个体', groupEn: 'C. Lab Escape / Numbered Subject', ontologyLevel: 4, def: '第一识别是收容事故后唯一站在走廊尽头的幸存者。造型入口：防爆门碎片、烧焦袖口、警报灯映红的脸、被迫学会不发声的呼吸。母题：灾难之后，身体携带了事故报告无法写清的部分。张力：他不是灾难英雄，重点是惊吓后的冷静和不知道自己为何活下来的不安。视觉证据：破裂封条、逃生路线箭头、血迹不明来源、攥紧的门把。边界：避免普通末日幸存者。', defEn: 'First read: the only survivor standing at the end of the corridor after containment failure. Styling entry: blast-door fragments, scorched cuffs, alarm-red face, and breathing trained to make no sound. Motif: after disaster, the body carries what the incident report cannot write. Tension: not a disaster hero; focus on post-shock calm and unease about why they survived. Visual evidence: broken seals, escape-route arrows, blood of unclear source, and a clenched door handle. Boundary: avoid generic apocalypse survivor.', tags: ['containment_break', 'survivor'] },

  { id: 'gene_hybrid_child', name: '基因混合儿童', nameEn: 'Gene-Hybrid Child', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, risk: 'medium', def: '第一识别是人类儿童轮廓里混入了少量可读的非人基因特征。造型入口：耳形微变、皮肤细纹、校服或日常衣物被身体差异顶出不合身、对镜子过度谨慎。母题：成长过程同时也是分类失败。张力：保持人形核心，不要立刻变成完整怪物。视觉证据：体检记录、改造许可贴、同龄衣物不适配、轻微防御姿态。边界：避免可爱宠物化或猎奇儿童。', defEn: 'First read: a human child silhouette carrying small but readable nonhuman gene traits. Styling entry: altered ear shape, fine skin pattern, school or daily clothes made ill-fitting by bodily difference, and excessive caution toward mirrors. Motif: growing up as a failure of classification. Tension: keep the human core; do not jump into a full monster. Visual evidence: health records, modification permit sticker, age-group clothes fitting wrong, and slight defensive posture. Boundary: avoid cute pet coding or spectacle child.', tags: ['gene_hybrid', 'child'] },
  { id: 'chimera_schoolboy', name: '嵌合体男学生', nameEn: 'Chimera Schoolboy', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, def: '第一识别是校服秩序压不住身体嵌合差异的男学生。造型入口：袖口藏爪、颈侧鳞片或绒毛区、背包带避开异常肩胛、站队时总留出距离。母题：学校把差异训练成纪律问题。张力：不是怪物校园，而是日常规则如何逼他隐藏身体。视觉证据：校牌、体检免除单、磨坏袖口、同学视线造成的收缩姿态。边界：避免普通兽耳少年或校园超能力主角。', defEn: 'First read: a schoolboy whose uniform order cannot contain chimera bodily difference. Styling entry: claws hidden in cuffs, scales or fur patches at the neck, backpack strap avoiding abnormal scapula, and keeping distance in line. Motif: school turning difference into discipline problem. Tension: not monster school; show how daily rules force body concealment. Visual evidence: student badge, PE exemption note, worn cuffs, and a shrinking posture under classmates gaze. Boundary: avoid generic animal-eared boy or school superpower hero.', tags: ['chimera', 'schoolboy'] },
  { id: 'gill_lung_swimmer', name: '鳃肺泳者', nameEn: 'Gill-Lung Swimmer', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, def: '第一识别是同时依赖肺和鳃生活的泳者。造型入口：颈侧鳃裂、潮湿训练服、防水药盒、游泳姿态比走路更自然。母题：呼吸系统决定社会空间。张力：他不是人鱼，重点是岸上窒息感、水中自由和医疗维护。视觉证据：盐水喷雾、颈部保护贴、湿发、陆地上微张的嘴。边界：避免浪漫海妖或普通游泳运动员。', defEn: 'First read: a swimmer living through both lungs and gills. Styling entry: side-neck gill slits, damp training wear, waterproof medicine case, and a body more natural swimming than walking. Motif: respiratory system decides social space. Tension: not a mermaid; focus on land suffocation, water freedom, and medical upkeep. Visual evidence: saline spray, neck protection patch, wet hair, and slightly open mouth on land. Boundary: avoid romantic siren or generic swimmer.', tags: ['gill', 'swimmer', 'hybrid'] },
  { id: 'antler_growth_girl', name: '鹿角生长女孩', nameEn: 'Antler-Growth Girl', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, def: '第一识别是头顶鹿角仍在生长期、日常动作都被它改写的女孩。造型入口：发际支撑带、角根红痕、宽领外套、过门时低头和不愿被摸头的警惕。母题：美丽特征带来真实负担。张力：鹿角不是装饰，必须影响疼痛、空间和社交边界。视觉证据：保护套、换角记录、角尖缠布、镜前调整姿态。边界：避免森林仙女或普通鹿角饰品。', defEn: 'First read: a girl whose antlers are still growing and rewriting daily movement. Styling entry: hairline support bands, red marks at antler roots, wide-collar coat, lowering head through doors, and alertness against being touched. Motif: beautiful trait as real burden. Tension: antlers are not decoration; they must affect pain, space, and social boundary. Visual evidence: protective caps, growth records, wrapped tips, and posture adjustments before mirror. Boundary: avoid forest fairy or antler accessory.', tags: ['antler', 'girl', 'growth'] },
  { id: 'feather_spine_model', name: '羽脊模特', nameEn: 'Feather-Spine Model', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, def: '第一识别是脊柱沿线长出羽列、并被时装镜头利用的模特。造型入口：背部开窗服、羽根皮肤红点、走台时控制背部张合、摄影师要求她展示异常。母题：身体异变被商业审美征用。张力：不要只是漂亮羽毛，重点是疼痛、展示和职业化表情之间的冲突。视觉证据：掉落羽绒、固定夹、冷光棚、僵住的肩胛。边界：避免天使翅膀或普通羽毛披肩。', defEn: 'First read: a model whose spine grows feather rows exploited by fashion camera. Styling entry: back-window garment, red follicle points, controlled back spreading on runway, and photographers asking her to display the anomaly. Motif: bodily mutation appropriated by commercial beauty. Tension: not pretty feathers alone; focus on pain, display, and professional expression. Visual evidence: fallen down, clamps, cold studio light, and stiff scapulae. Boundary: avoid angel wings or feather shawl.', tags: ['feather_spine', 'model'] },
  { id: 'claw_hand_pianist', name: '爪手钢琴家', nameEn: 'Claw-Hand Pianist', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, def: '第一识别是爪化手指仍坚持触键的钢琴家。造型入口：修短但无法完全隐藏的爪、黑礼服、键面划痕、手套开孔和极慢落指。母题：精细艺术与捕猎器官冲突。张力：不要做成怪物炫技，重点是控制、羞耻和重新训练的手。视觉证据：破损琴键、指尖保护套、谱页批注、紧绷手腕。边界：避免普通兽人音乐家或恐怖利爪。', defEn: 'First read: a pianist still playing through clawed fingers. Styling entry: trimmed but unhideable claws, black formalwear, scratched keys, pierced gloves, and extremely slow keystrokes. Motif: fine art conflicting with hunting organs. Tension: not monster virtuosity; focus on control, shame, and retrained hands. Visual evidence: damaged keys, fingertip guards, annotated score, and tense wrists. Boundary: avoid generic beast musician or horror claws.', tags: ['claw_hand', 'pianist'] },
  { id: 'lab_wolf_daughter', name: '实验室狼女儿', nameEn: 'Lab-Wolf Daughter', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, risk: 'high', def: '第一识别是被实验室命名为“女儿”的狼性嵌合体。造型入口：护颈项圈、灰毛沿肩背生长、家庭照片式编号牌、既会靠近又随时后撤的站姿。母题：亲属称呼掩盖了培养与驯化。张力：她不是狼人，也不是宠物，危险来自亲密语言和实验所有权重叠。视觉证据：犬齿、爪套、领牌、观察员手势。边界：避免普通狼女或宠物少女。', defEn: 'First read: a wolf chimera named "daughter" by the laboratory. Styling entry: neck guard collar, grey fur along shoulders and back, family-photo-like code plate, and a stance that approaches then retreats. Motif: kinship language hiding cultivation and training. Tension: not a werewolf or pet; danger comes from intimacy language overlapping experiment ownership. Visual evidence: canines, claw caps, collar tag, and observer gestures. Boundary: avoid generic wolf girl or pet-coded girl.', tags: ['wolf_chimera', 'daughter', 'lab'] },
  { id: 'amphibian_skin_nurse', name: '两栖皮肤护士', nameEn: 'Amphibian-Skin Nurse', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, def: '第一识别是皮肤需要保持湿润、却在干燥医院里工作的护士。造型入口：湿润袖套、颈部斑纹、喷雾瓶、橡胶鞋和频繁补水但动作仍专业的手。母题：照护者自己的身体也需要环境照护。张力：她不是青蛙怪物，重点是工作流程与皮肤需求冲突。视觉证据：保湿仪、潮湿手套、病历夹水印、平静而疲惫的眼神。边界：避免卡通蛙人或普通护士。', defEn: 'First read: a nurse with amphibian skin needs moisture while working in a dry hospital. Styling entry: damp sleeves, neck markings, spray bottle, rubber shoes, and professional hands that keep rehydrating. Motif: the caregiver body also needs environmental care. Tension: not a frog monster; focus on conflict between workflow and skin requirement. Visual evidence: humidifier, wet gloves, water marks on chart, calm tired eyes. Boundary: avoid cartoon frog person or generic nurse.', tags: ['amphibian_skin', 'nurse'] },
  { id: 'transparent_blood_heir', name: '透明血继承人', nameEn: 'Transparent-Blood Heir', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 4, risk: 'medium', def: '第一识别是拥有透明或浅色血液、被家族当成特殊血统证明的继承人。造型入口：浅色血管、贵族式衣领、采血管吊坠、过度保护的手套和不允许受伤的姿态。母题：血统可见化成身体脆弱。张力：不要写成普通贵族，重点是继承权、样本价值和对伤口的恐惧。视觉证据：透明药瓶、浅色淤痕、家族纹章、被护住的手腕。边界：避免吸血鬼或玻璃人。', defEn: 'First read: an heir with transparent or pale blood treated as proof of special lineage. Styling entry: pale veins, aristocratic collar, blood-vial pendant, overprotective gloves, and posture that must not be wounded. Motif: lineage made visible as bodily fragility. Tension: not a generic noble; focus on inheritance, sample value, and fear of injury. Visual evidence: clear vial, pale bruises, family crest, protected wrist. Boundary: avoid vampire or glass-person trope.', tags: ['transparent_blood', 'heir'] },
  { id: 'bioengineered_angel_boy', name: '生物工程天使少年', nameEn: 'Bioengineered Angel Boy', group: 'D. 基因混合 / 人兽嵌合', groupEn: 'D. Gene Hybrid / Human-Animal Chimera', ontologyLevel: 5, risk: 'high', def: '第一识别是“天使”外观由生物工程制造出来的少年。造型入口：不完整羽芽、背部支架、无菌白衣、实验赞助标识和过于安静的垂眼。母题：神圣形象被实验室量产。张力：不要真正宗教化，重点是拟神外观、身体疼痛和被展示的商业奇迹。视觉证据：羽根缝线、培养记录、冷白灯、背部固定带。边界：避免传统天使或偶像美少年。', defEn: 'First read: a boy whose angelic appearance is bioengineered. Styling entry: incomplete wing buds, back braces, sterile white clothing, sponsor marks, and overly quiet lowered eyes. Motif: sacred imagery mass-produced by laboratory. Tension: avoid real religious transcendence; focus on godlike exterior, bodily pain, and displayed commercial miracle. Visual evidence: wing-root stitches, growth records, cold white light, back fixation straps. Boundary: avoid traditional angel or idol pretty boy.', tags: ['bioengineered', 'angel_boy'] },

  { id: 'drug_enhanced_soldier', name: '药物强化士兵', nameEn: 'Drug-Enhanced Soldier', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是靠药物维持战斗效率的士兵。造型入口：注射贴、战术服内药包、瞳孔微扩、肌肉紧绷但表情过度空白。母题：勇敢被化学流程替代。张力：他不是超人，强化来自依赖、剂量和停药恐惧。视觉证据：自动注射器、计时手环、汗水、咬紧牙关。边界：避免普通特种兵或科幻狂战士。', defEn: 'First read: a soldier whose combat efficiency is maintained by drugs. Styling entry: injection patches, medicine pack inside tactical gear, slightly dilated pupils, tense muscle with overly blank expression. Motif: bravery replaced by chemical procedure. Tension: not superhuman; enhancement comes from dependence, dosage, and fear of withdrawal. Visual evidence: auto-injector, timer wristband, sweat, clenched jaw. Boundary: avoid generic special forces or sci-fi berserker.', tags: ['drug_enhanced', 'soldier'] },
  { id: 'hormone_trial_girl', name: '激素试验女孩', nameEn: 'Hormone-Trial Girl', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是身体发育节奏被激素试验改变的年轻女性。造型入口：药盒、体征记录表、过度合身或突然不合身的衣物、对自己轮廓的陌生。母题：成长被临床参数接管。张力：保持成人边界，不把身体变化写成凝视猎奇。视觉证据：贴片、量尺、镜前迟疑、压低的肩。边界：避免青春期猎奇或普通美容项目。', defEn: 'First read: a young adult woman whose body rhythm has been altered by hormone trials. Styling entry: pill case, vital records, clothes too fitted or suddenly ill-fitting, and unfamiliarity with her own outline. Motif: growth taken over by clinical parameters. Tension: keep adult boundaries and avoid voyeuristic body change. Visual evidence: patches, measuring tape, hesitation before mirror, lowered shoulders. Boundary: avoid puberty spectacle or ordinary beauty treatment.', tags: ['hormone_trial', 'body_change'] },
  { id: 'steroid_boxer', name: '类固醇拳手', nameEn: 'Steroid Boxer', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是肌肉、怒意和药物副作用一起挤在拳台上的拳手。造型入口：绷带拳套、颈部粗胀、皮肤油亮、眼神易怒和更衣室里藏起的药瓶。母题：竞技身体被胜负压力化学化。张力：不要只写强壮，要写失控边缘、羞耻和职业规则。视觉证据：针孔、称重牌、汗湿毛巾、过紧护齿。边界：避免普通肌肉拳手。', defEn: 'First read: a boxer where muscle, anger, and drug side effects crowd the ring together. Styling entry: wrapped gloves, swollen neck, oily skin, irritable gaze, and bottles hidden in locker room. Motif: athletic body chemically pressured by winning. Tension: not just strength; show edge of loss of control, shame, and sport rules. Visual evidence: needle marks, weigh-in tag, wet towel, too-tight mouthguard. Boundary: avoid generic muscular boxer.', tags: ['steroid', 'boxer'] },
  { id: 'sleep_suppressed_worker', name: '睡眠抑制工人', nameEn: 'Sleep-Suppressed Worker', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是靠抑制睡眠药物撑过连续班次的工人。造型入口：工装、咖啡因贴片、眼白血丝、反应慢半拍但动作仍机械准确。母题：资本把睡眠从身体里扣除。张力：现实疲劳比超能力重要。视觉证据：班次表、药贴、手抖、午餐盒没打开。边界：避免普通熬夜角色或赛博超人。', defEn: 'First read: a worker pushing through continuous shifts with sleep-suppression drugs. Styling entry: workwear, caffeine patches, bloodshot eyes, reactions half a beat slow while gestures remain mechanically accurate. Motif: labor subtracting sleep from the body. Tension: realistic fatigue matters more than superpower. Visual evidence: shift chart, drug patches, trembling hands, unopened lunchbox. Boundary: avoid generic night-owl or cyber superhuman.', tags: ['sleep_suppressed', 'worker'] },
  { id: 'beauty_serum_socialite', name: '美容血清名媛', nameEn: 'Beauty-Serum Socialite', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是用实验血清维持社交场美貌的名媛。造型入口：高级礼服、颈侧注射点、冷藏小盒、妆容无瑕但皮肤边缘出现不稳定红晕。母题：阶层美学建立在药物维护上。张力：她不是普通贵妇，优雅背后是剂量、保密和崩坏风险。视觉证据：血清瓶、丝手套、镜中检查、微笑过稳。边界：避免普通美容广告或吸血鬼。', defEn: 'First read: a socialite maintaining event beauty through experimental serum. Styling entry: high-end gown, neck injection point, refrigerated case, flawless makeup with unstable blush at skin edges. Motif: class beauty built on pharmaceutical maintenance. Tension: not a generic lady; elegance hides dosage, secrecy, and collapse risk. Visual evidence: serum vial, silk gloves, mirror check, smile too stable. Boundary: avoid beauty ad or vampire trope.', tags: ['beauty_serum', 'socialite'] },
  { id: 'memory_drug_student', name: '记忆药学生', nameEn: 'Memory-Drug Student', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, def: '第一识别是依赖记忆药物应付考试和人生选择的学生。造型入口：药片夹在课本里、耳边速记、太阳穴贴、眼神清醒得不自然。母题：学习能力变成可购买剂量。张力：不是天才，而是把自我压成考试缓存的人。视觉证据：复习卡、空药板、鼻血纸巾、过度整齐笔记。边界：避免普通学霸或黑客学生。', defEn: 'First read: a student depending on memory drugs for exams and life choices. Styling entry: pills tucked inside textbooks, shorthand at the ear, temple patches, and eyes unnaturally alert. Motif: learning ability becomes purchasable dosage. Tension: not a genius, but someone compressing selfhood into exam cache. Visual evidence: flashcards, empty blister packs, nosebleed tissue, overly neat notes. Boundary: avoid generic top student or hacker kid.', tags: ['memory_drug', 'student'] },
  { id: 'painkiller_monk', name: '止痛药僧侣', nameEn: 'Painkiller Monk', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是把忍痛修行和止痛药依赖混在一起的僧侣。造型入口：素袍、药瓶念珠、膝盖旧伤、平静表情下迟钝的痛觉反应。母题：苦修被药物管理改写。张力：不要神圣化药物，重点是纪律、疼痛和身体诚实之间的矛盾。视觉证据：膏药、药片、磨损蒲团、慢半拍的跪起。边界：避免真实宗教冒犯或普通病人。', defEn: 'First read: a monk mixing pain endurance practice with painkiller dependence. Styling entry: plain robe, pill-bottle rosary, old knee injuries, and delayed pain response beneath calm expression. Motif: ascetic discipline rewritten by medication management. Tension: do not sanctify drugs; focus on discipline, pain, and bodily honesty. Visual evidence: plasters, pills, worn cushion, delayed kneeling and rising. Boundary: avoid real religious offense or generic patient.', tags: ['painkiller', 'monk'] },
  { id: 'combat_stimulant_courier', name: '战斗兴奋剂信使', nameEn: 'Combat-Stimulant Courier', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是靠战斗兴奋剂穿过危险路段的信使。造型入口：轻装背包、注射笔、瞳孔放大、过快呼吸和仍然把包护在胸前的路线感。母题：速度被化学风险购买。张力：他不是酷跑者，身体随时可能在任务后崩塌。视觉证据：路线图、心率贴、汗水、颤抖手指。边界：避免普通快递员或超能跑者。', defEn: 'First read: a courier crossing dangerous routes through combat stimulants. Styling entry: light pack, injection pen, dilated pupils, rapid breathing, and route sense while protecting the parcel against the chest. Motif: speed purchased through chemical risk. Tension: not a cool runner; the body may collapse after delivery. Visual evidence: route map, heart-rate patch, sweat, trembling fingers. Boundary: avoid generic courier or super-speed hero.', tags: ['stimulant', 'courier'] },
  { id: 'anti_ageing_patient', name: '抗衰老病人', nameEn: 'Anti-Ageing Patient', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 2, risk: 'medium', def: '第一识别是被抗衰疗程困住、年龄感与身体证据互相矛盾的人。造型入口：平滑皮肤旁的老手、诊疗腕带、高级病号服、对皱纹过度警觉的手势。母题：永葆年轻成为慢性病。张力：不要美容胜利，重点是维护成本、恐惧和身份年龄错位。视觉证据：疗程表、冷藏针剂、细小副作用斑、镜前检查。边界：避免普通年轻化或吸血鬼。', defEn: 'First read: a patient trapped in anti-ageing treatment, with age impression and bodily evidence contradicting each other. Styling entry: smooth skin beside old hands, treatment wristband, refined patient wear, and gestures over-alert to wrinkles. Motif: eternal youth as chronic illness. Tension: not beauty victory; focus on maintenance cost, fear, and age-identity mismatch. Visual evidence: treatment schedule, chilled injections, tiny side-effect spots, mirror inspection. Boundary: avoid simple rejuvenation or vampire trope.', tags: ['anti_ageing', 'patient'] },
  { id: 'withdrawal_oracle', name: '戒断预言者', nameEn: 'Withdrawal Oracle', group: 'E. 药物改造 / 激素身体', groupEn: 'E. Drug Modification / Hormonal Body', ontologyLevel: 3, risk: 'high', def: '第一识别是戒断幻觉被旁人当成预言的人。造型入口：发抖手腕、干裂嘴唇、记录纸、被汗浸湿的衣领和说话前像在忍住痛的停顿。母题：身体危机被误读为神秘知识。张力：不要浪漫化成天启先知，重点是依赖、痛苦和他人利用。视觉证据：空药瓶、梦话记录、脉搏带、避光眼神。边界：避免普通神棍或瘾君子刻板印象。', defEn: 'First read: a person whose withdrawal hallucinations are treated by others as prophecy. Styling entry: trembling wrists, cracked lips, record paper, sweat-soaked collar, and pauses before speech like holding pain back. Motif: bodily crisis misread as mystical knowledge. Tension: do not romanticize into apocalypse prophet; focus on dependence, suffering, and exploitation by others. Visual evidence: empty bottles, dream-speech notes, pulse band, light-avoiding eyes. Boundary: avoid generic charlatan or addict stereotype.', tags: ['withdrawal', 'oracle'] },

  { id: 'bio_interface_girl', name: '生物接口女孩', nameEn: 'Bio-Interface Girl', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 4, def: '第一识别是身体上长出可连接活体系统的接口女孩。造型入口：腕部软质端口、皮肤边缘微红、设备线像触须一样靠近、她把手收在身前保护接口。母题：连接能力同时也是被侵入的入口。张力：不要变成普通赛博插孔，必须保留血肉湿度和护理成本。视觉证据：消毒棉、接口盖、局部渗液、谨慎触碰。边界：避免机械义体化。', defEn: 'First read: a girl whose body grows ports for living systems. Styling entry: soft wrist ports, reddened skin edges, device lines approaching like tendrils, and hands kept close to protect the ports. Motif: connectivity is also an invasion point. Tension: not a generic cyber socket; keep flesh moisture and care cost. Visual evidence: swabs, port caps, slight secretion, cautious touch. Boundary: avoid mechanical prosthetic coding.', tags: ['bio_interface', 'girl'] },
  { id: 'living_cable_operator', name: '活体电缆操作员', nameEn: 'Living-Cable Operator', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 4, def: '第一识别是用活体电缆操作设备的人。造型入口：肩背缠绕的肉质线缆、绝缘围裙、手指像在安抚动物一样接线。母题：操作机器变成照料半活物。张力：线缆不能只是红色装饰，要有温度、反应和依赖关系。视觉证据：线缆脉动、固定夹、咬痕手套、操作台潮湿痕。边界：避免普通电工或纯触手怪。', defEn: 'First read: an operator controlling devices through living cables. Styling entry: fleshy cables around shoulders and back, insulated apron, and fingers connecting as if soothing animals. Motif: operating machines becomes caring for half-living matter. Tension: cables cannot be red decoration; they need warmth, response, and dependence. Visual evidence: pulsing cords, clamps, bitten gloves, damp console traces. Boundary: avoid generic electrician or pure tentacle monster.', tags: ['living_cable', 'operator'] },
  { id: 'organ_console_pilot', name: '器官控制台驾驶员', nameEn: 'Organ-Console Pilot', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 5, eras: future, def: '第一识别是驾驶台像器官一样呼吸、驾驶员必须与其同步的人。造型入口：坐舱束带、掌心按在肉质控制面、胸腔呼吸节奏被仪表牵引。母题：载具不再被操控，而是被共同代谢。张力：他不是机甲驾驶员，重点是恶心的亲密、同步疲劳和功能依赖。视觉证据：器官按钮、生命读数、汗水、座椅包裹身体。边界：避免硬科幻控制台。', defEn: 'First read: a pilot whose console breathes like an organ and requires bodily synchronization. Styling entry: cockpit straps, palms on fleshy controls, and chest rhythm pulled by instruments. Motif: vehicle no longer controlled but co-metabolized. Tension: not a mecha pilot; focus on intimate discomfort, sync fatigue, and functional dependence. Visual evidence: organ buttons, life readouts, sweat, seat wrapping the body. Boundary: avoid hard-sci-fi console.', tags: ['organ_console', 'pilot'] },
  { id: 'flesh_keyboard_clerk', name: '肉键盘职员', nameEn: 'Flesh-Keyboard Clerk', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 4, def: '第一识别是每天在肉质键盘上录入数据的低阶职员。造型入口：办公室衬衫、手指绷带、微微起伏的键面、他敲击时像怕弄疼对方。母题：行政劳动进入活体界面。张力：荒诞感要贴近日常办公，而不是变成怪物秀。视觉证据：文件夹、潮湿键帽、消毒纸、疲惫眼镜。边界：避免普通办公室或恶心道具堆砌。', defEn: 'First read: a low-level clerk typing daily on a flesh keyboard. Styling entry: office shirt, bandaged fingers, gently rising key surface, and typing as if afraid to hurt it. Motif: administrative labor entering living interface. Tension: absurdity should stay close to office routine, not monster spectacle. Visual evidence: folders, damp keys, disinfectant wipes, tired glasses. Boundary: avoid generic office worker or gross prop pile.', tags: ['flesh_keyboard', 'clerk'] },
  { id: 'nerve_flower_singer', name: '神经花歌手', nameEn: 'Nerve-Flower Singer', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 5, def: '第一识别是喉部和神经花相连、歌声由活体花器共同放大的歌手。造型入口：颈侧花茎、舞台麦克风退到次要位置、唱歌时花瓣随声张合。母题：表演嗓音变成共生器官。张力：不要仙女化，重点是疼痛、呼吸控制和观众对异常声源的凝视。视觉证据：喉部固定带、花粉、声波读数、压住胸口的手。边界：避免普通花妖歌姬。', defEn: 'First read: a singer whose throat connects to nerve flowers that amplify the voice. Styling entry: stems at the neck, stage microphone made secondary, and petals opening with each note. Motif: performance voice becomes symbiotic organ. Tension: avoid fairy prettiness; focus on pain, breath control, and audience gaze toward the abnormal sound source. Visual evidence: throat harness, pollen, waveform readouts, hand pressing chest. Boundary: avoid generic flower siren.', tags: ['nerve_flower', 'singer'] },
  { id: 'living_mask_actor', name: '活体面具演员', nameEn: 'Living-Mask Actor', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 4, def: '第一识别是面具会呼吸、贴合并反向影响表情的演员。造型入口：剧场服、面具边缘与皮肤粘连、卸妆台上的生理盐水和不确定哪张脸在表演的眼神。母题：角色不再是扮演，而是附着。张力：不要普通戏剧面具，重点是职业表演和活体依赖的边界模糊。视觉证据：面具脉动、泪痕、镜灯、揭不开的边缘。边界：避免鬼面具套路。', defEn: 'First read: an actor whose mask breathes, adheres, and pushes expression back. Styling entry: theater costume, mask edge stuck to skin, saline on makeup table, and eyes unsure which face is performing. Motif: role is no longer played but attached. Tension: not a normal theater mask; focus on blurred boundary between craft and living dependence. Visual evidence: pulsing mask, tear tracks, mirror bulbs, unpeelable edges. Boundary: avoid haunted-mask trope.', tags: ['living_mask', 'actor'] },
  { id: 'bio_port_nurse', name: '生物端口护士', nameEn: 'Bio-Port Nurse', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 4, risk: 'medium', def: '第一识别是专门护理活体端口、比病人更懂端口脾气的护士。造型入口：护理制服、软管刷、温度贴、手套上留下黏液痕和极轻的操作动作。母题：医疗护理转向人机血肉接口。张力：她不是性感护士，专业性来自温柔、精准和对感染风险的警惕。视觉证据：端口盖、消毒托盘、记录卡、低头检查姿态。边界：避免普通护士或科幻机械维修员。', defEn: 'First read: a nurse specialized in caring for living ports, knowing their temperament better than patients do. Styling entry: nurse uniform, tube brush, temperature patches, mucus traces on gloves, and very light handling. Motif: medical care turning toward flesh-machine interfaces. Tension: not a sexy nurse; professionalism comes from gentleness, precision, and infection vigilance. Visual evidence: port covers, sterilization tray, record card, lowered inspection posture. Boundary: avoid generic nurse or sci-fi mechanical technician.', tags: ['bio_port', 'nurse'] },
  { id: 'skin_screen_influencer', name: '皮肤屏幕网红', nameEn: 'Skin-Screen Influencer', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 4, risk: 'medium', def: '第一识别是皮肤能显示画面、把身体表面变成直播界面的网红。造型入口：裸露手臂或肩背上的低亮度影像、补光灯、遮瑕贴和随时检查观众反馈的笑容。母题：自我展示直接写在皮肤上。张力：她不是发光美人，重点是隐私、疲劳和皮肤作为平台的维护成本。视觉证据：像素斑、充能贴、评论倒影、过度训练的表情。边界：避免普通网红或全息投影替身。', defEn: 'First read: an influencer whose skin displays images, turning body surface into live interface. Styling entry: dim images on exposed arms or back, fill light, concealer patches, and a smile checking audience feedback. Motif: self-display written directly onto skin. Tension: not a glowing beauty; focus on privacy, fatigue, and maintenance cost of skin as platform. Visual evidence: pixel spots, charging patches, comment reflections, overtrained expression. Boundary: avoid generic influencer or hologram avatar.', tags: ['skin_screen', 'influencer'] },
  { id: 'umbilical_data_child', name: '脐带数据儿童', nameEn: 'Umbilical-Data Child', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 5, risk: 'medium', def: '第一识别是身体仍通过脐带式数据线连接照护系统的儿童。造型入口：腹部软端口、拖在身后的护套线、小背心、照护员不敢拉远的距离。母题：出生后的依赖被技术延长。张力：保持非猎奇，重点是照护、限制和无法真正独立移动。视觉证据：线缆卷盘、生命读数、玩具被线缠住、回头确认连接的眼神。边界：避免恐怖婴儿或普通儿童病号。', defEn: 'First read: a child still connected to a care system through an umbilical data cord. Styling entry: soft abdominal port, sheathed cable trailing behind, small vest, and caregiver distance that cannot stretch too far. Motif: post-birth dependence extended by technology. Tension: keep non-spectacular; focus on care, restriction, and inability to move truly independently. Visual evidence: cable reel, life readout, toy tangled in cord, eyes checking connection. Boundary: avoid horror baby or generic child patient.', tags: ['umbilical_data', 'child'] },
  { id: 'organ_radio_priest', name: '器官电台祭司', nameEn: 'Organ-Radio Priest', group: 'F. 生物接口 / 活体装置', groupEn: 'F. Bio Interface / Living Device', ontologyLevel: 5, def: '第一识别是用活体器官电台接收群体低语的祭司。造型入口：胸前肉质接收器、手调旋钮像触摸伤口、朴素仪式服和听见信号时突然停住的脸。母题：广播技术退回身体器官。张力：不要神棍化，重点是收听、疼痛和社群依赖这台活设备。视觉证据：频率纸条、搏动天线、耳边血痕、低声复述。边界：避免普通电台主持或宗教光环。', defEn: 'First read: a priest receiving communal whispers through a living organ radio. Styling entry: fleshy receiver on chest, fingers tuning knobs like touching wounds, plain ritual clothing, and a face freezing when signal arrives. Motif: broadcast technology returning to bodily organs. Tension: avoid charlatan mysticism; focus on listening, pain, and community dependence on this living device. Visual evidence: frequency notes, pulsing antenna, blood at ear, low repetition. Boundary: avoid radio host or religious halo.', tags: ['organ_radio', 'priest'] },

  { id: 'runaway_experiment', name: '失控实验体', nameEn: 'Runaway Experiment', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 5, risk: 'high', def: '第一识别是实验已经越过可控阈值、身体仍在现场失控变化的人。造型入口：破裂束带、皮肤鼓动、警报红光、动作像在和自己身体拔河。母题：科学流程被身体反向拖走。张力：不要只做怪物爆发，要让“刚刚失控”的瞬间可读。视觉证据：断开的传感线、翻倒推车、呼吸雾、手掌撑地。边界：避免普通狂暴怪物。', defEn: 'First read: an experiment past the control threshold, with the body still changing on site. Styling entry: broken restraints, moving skin, alarm red light, and motion like wrestling against the body itself. Motif: scientific procedure dragged backward by flesh. Tension: not just monster eruption; make the just-lost-control moment readable. Visual evidence: snapped sensor lines, overturned cart, breath fog, palms braced on floor. Boundary: avoid generic rage monster.', tags: ['runaway_experiment', 'outbreak'] },
  { id: 'mutation_outbreak_girl', name: '突变爆发女孩', nameEn: 'Mutation-Outbreak Girl', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 5, risk: 'high', def: '第一识别是突变正在从衣服缝隙和皮肤边界爆发的年轻女性。造型入口：撕裂袖口、新生结构顶开衣层、恐惧与疼痛混合的脸、周围人后退造成的空场。母题：身体变化比她的意愿更快。张力：避免性感异变，重点是失去控制和仍想保持人形姿态。视觉证据：裂开的扣子、皮下光泽、抓痕、退后的脚印。边界：避免普通怪物女孩。', defEn: 'First read: a young woman whose mutation is erupting through seams and skin boundary. Styling entry: torn cuffs, new structures pushing clothing open, a face mixing fear and pain, and empty space made by others stepping back. Motif: bodily change faster than her will. Tension: avoid sexy mutation; focus on losing control while trying to keep human posture. Visual evidence: broken buttons, subdermal sheen, scratch marks, retreating footprints. Boundary: avoid generic monster girl.', tags: ['mutation_outbreak', 'girl'] },
  { id: 'failed_super_soldier', name: '失败超级士兵', nameEn: 'Failed Super Soldier', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 4, risk: 'high', def: '第一识别是强化计划没有产出英雄，只留下难以维护的失败士兵。造型入口：过重肌肉、不协调义务装备、医疗标签盖住军牌、走路时身体明显不稳定。母题：军事幻想在人体上失败。张力：他不是强者，而是被性能指标伤害的人。视觉证据：停用印章、破护甲、旧注射点、空洞服从眼神。边界：避免普通超级英雄或反派巨汉。', defEn: 'First read: a super-soldier program that produced no hero, only a body hard to maintain. Styling entry: excessive muscle, mismatched duty gear, medical tags over dog tags, and visibly unstable walking. Motif: military fantasy failing on the human body. Tension: not a strongman, but someone injured by performance metrics. Visual evidence: decommission stamps, broken armor, old injection points, hollow obedient eyes. Boundary: avoid superhero or villain brute.', tags: ['failed_super_soldier', 'military'] },
  { id: 'containment_siren', name: '收容警报体', nameEn: 'Containment Siren', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 5, risk: 'high', def: '第一识别是身体本身会触发或发出收容警报的个体。造型入口：喉部警示器官、红色频闪映在皮肤上、她越想安静越发出警报。母题：危险标识从设施转移到身体。张力：不要写成唱歌怪物，重点是无法隐藏、无法停止和被制度标记。视觉证据：警报灯、捂住喉咙、声波记录、工作人员耳罩。边界：避免普通海妖或报警器道具。', defEn: 'First read: an individual whose body triggers or emits containment alarms. Styling entry: warning organ at the throat, red strobes on skin, and alarm growing as she tries to be quiet. Motif: danger signage moving from facility to body. Tension: not a singing monster; focus on inability to hide, inability to stop, and institutional marking. Visual evidence: alarm light, hands over throat, waveform record, staff ear protection. Boundary: avoid siren creature or alarm prop.', tags: ['containment_siren', 'alarm'] },
  { id: 'panic_room_subject', name: '恐慌室对象', nameEn: 'Panic-Room Subject', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 4, risk: 'high', def: '第一识别是被锁进恐慌室后，房间和身体一起进入过载的人。造型入口：软墙、抓痕、监控镜头、凌乱呼吸和努力把自己缩小的姿态。母题：收容空间制造而不是解决恐慌。张力：不要泛化成精神病房，重点是实验对象、空间压力和被观察的崩溃。视觉证据：墙上指印、心率屏、门缝光、抱膝姿态。边界：避免廉价疯癫。', defEn: 'First read: a subject locked in a panic room until both room and body overload. Styling entry: padded walls, scratch marks, camera lens, broken breathing, and posture trying to become smaller. Motif: containment space manufacturing rather than solving panic. Tension: do not generalize into asylum imagery; focus on subject status, spatial pressure, and observed breakdown. Visual evidence: fingerprints on wall, heart-rate screen, light under door, knees hugged. Boundary: avoid cheap madness.', tags: ['panic_room', 'subject'] },
  { id: 'overgrown_body_boy', name: '过度生长少年', nameEn: 'Overgrown-Body Boy', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 4, risk: 'medium', def: '第一识别是身体生长速度超过年龄和衣物承载的少年。造型入口：短一截的袖裤、关节疼痛绷带、低头穿门、表情仍有少年感但骨架已经过大。母题：成长被实验放大成负担。张力：不要写成巨人怪物，重点是年龄错位、疼痛和羞怯。视觉证据：量身标尺、破鞋、膝肘护具、蜷缩坐姿。边界：避免普通高个少年。', defEn: 'First read: a boy whose body growth outpaces age and clothing. Styling entry: too-short sleeves and pants, joint-pain bandages, ducking through doors, a still-boyish expression on an oversized frame. Motif: growth amplified into burden by experiment. Tension: not a giant monster; focus on age mismatch, pain, and shyness. Visual evidence: measuring marks, torn shoes, knee and elbow braces, curled sitting posture. Boundary: avoid generic tall teen.', tags: ['overgrown_body', 'boy'] },
  { id: 'lab_fire_survivor', name: '实验室火灾幸存者', nameEn: 'Lab-Fire Survivor', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 3, risk: 'medium', def: '第一识别是实验室火灾后留下烧伤、烟尘和逃生记忆的人。造型入口：半烧病号服、烟熏皮肤、包扎手臂、闻到消毒水就僵住的表情。母题：事故把实验痕迹烧进身体。张力：不要灾难片英雄化，重点是幸存后的脆弱和对火光的反应。视觉证据：烧焦编号、急救毯、黑灰指尖、警报残影。边界：避免普通火灾幸存者。', defEn: 'First read: a person left with burns, soot, and escape memory after a lab fire. Styling entry: half-burned patient gown, smoke-stained skin, bandaged arms, and a face freezing at disinfectant smell. Motif: accident burning experiment traces into the body. Tension: no disaster-hero framing; focus on post-survival fragility and reaction to flame. Visual evidence: scorched code, emergency blanket, blackened fingertips, alarm afterimage. Boundary: avoid generic fire survivor.', tags: ['lab_fire', 'survivor'] },
  { id: 'uncontrolled_regeneration_patient', name: '失控再生病人', nameEn: 'Uncontrolled-Regeneration Patient', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 5, risk: 'high', def: '第一识别是伤口会过度再生、身体修复反而制造新问题的病人。造型入口：多余组织被束带压住、反复切除痕、医生手写限制、他对小伤口异常恐惧。母题：愈合能力变成失控生产。张力：不要当成不死超能力，重点是维护、疼痛和身体边界膨胀。视觉证据：压缩绷带、手术标记、过厚疤痕、避开尖锐物。边界：避免普通再生英雄。', defEn: 'First read: a patient whose wounds over-regenerate, making repair create new problems. Styling entry: excess tissue held by straps, repeated excision scars, handwritten medical limits, and abnormal fear of small cuts. Motif: healing power as uncontrolled production. Tension: not immortality power; focus on maintenance, pain, and expanding body boundary. Visual evidence: compression bandages, surgery marks, thick scars, avoiding sharp objects. Boundary: avoid regeneration hero.', tags: ['regeneration', 'patient'] },
  { id: 'voice_command_failed_android_flesh', name: '语音命令失效肉身', nameEn: 'Voice-Command-Failed Android Flesh', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 5, risk: 'high', eras: future, def: '第一识别是原本应响应语音命令的仿生肉身开始拒绝指令。造型入口：人工皮肤、耳后接收器、听到命令时僵硬微笑、身体动作和口头服从不同步。母题：服从系统在血肉层面失效。张力：不要普通机器人叛逃，重点是“像人一样的肉身”不再听话。视觉证据：指令屏、皮肤接缝、延迟动作、操作者惊讶。边界：避免纯机械安卓。', defEn: 'First read: a synthetic flesh body meant to obey voice commands beginning to refuse. Styling entry: artificial skin, receiver behind ear, stiff smile when hearing orders, body action unsynced from verbal compliance. Motif: obedience system failing at flesh level. Tension: not robot rebellion; focus on human-like flesh no longer obeying. Visual evidence: command screen, skin seams, delayed motion, operator shock. Boundary: avoid pure mechanical android.', tags: ['voice_command', 'android_flesh'] },
  { id: 'biohazard_bride_escapee', name: '生化危机逃亡新娘', nameEn: 'Biohazard Bride Escapee', group: 'G. 失控试验 / 暴走个体', groupEn: 'G. Runaway Trial / Outbreak Individual', ontologyLevel: 4, risk: 'high', def: '第一识别是从生化隔离婚礼或实验婚配流程中逃出的新娘。造型入口：撕裂白纱、防护封条、捧花被当作样本袋、裙摆沾着消毒液和逃跑灰尘。母题：亲密仪式被危险协议撕开。张力：她不是普通落跑新娘，婚礼本身就是实验流程的一部分。视觉证据：污染标识、戒指隔着手套、警戒线、侧身逃离。边界：避免普通婚纱恐怖。', defEn: 'First read: a bride escaped from a biohazard wedding or experimental pairing protocol. Styling entry: torn veil, protective seals, bouquet turned sample bag, skirt stained with disinfectant and escape dust. Motif: intimate ritual torn open by danger protocol. Tension: not a runaway bride; the wedding itself was part of experiment workflow. Visual evidence: contamination signs, ring over glove, warning tape, body turning to flee. Boundary: avoid generic bridal horror.', tags: ['biohazard', 'bride', 'escapee'] },

  { id: 'clone_sister_number_three', name: '三号克隆姐妹', nameEn: 'Clone Sister Number Three', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 4, risk: 'medium', def: '第一识别是姐妹关系被编号系统切开的第三个克隆体。造型入口：相同校服或制服里的细微差异、三号标签、她努力制造不同发夹或站姿。母题：相似身体争夺个人性。张力：不要普通双胞胎，重点是编号、替代性和小差异的尊严。视觉证据：批次牌、重复照片、不同袖口折法、紧张侧眼。边界：避免克隆军团泛化。', defEn: 'First read: the third clone whose sisterhood is cut by numbering. Styling entry: tiny differences inside identical school or work uniform, Number Three tag, and attempts at a different hairclip or stance. Motif: similar bodies fighting for personhood. Tension: not twins; focus on number, replaceability, and dignity of small difference. Visual evidence: batch plate, repeated photos, different cuff fold, tense side glance. Boundary: avoid generic clone army.', tags: ['clone_sister', 'number_three'] },
  { id: 'batch_born_worker', name: '批量出生工人', nameEn: 'Batch-Born Worker', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 3, eras: industrialBio, def: '第一识别是从同一批次出生、直接进入劳动岗位的工人。造型入口：工服编号、相似脸孔中的疲惫差异、批次手册和熟练到不像个人选择的动作。母题：出生被生产排班吸收。张力：现实劳动感要压过科幻奇观。视觉证据：打卡牌、批次纹身、磨损手套、排队领工具。边界：避免普通工厂人群。', defEn: 'First read: a worker born in a batch and routed directly into labor. Styling entry: workwear number, fatigue differences among similar faces, batch manual, and movements too skilled to feel chosen. Motif: birth absorbed into production scheduling. Tension: realistic labor should outweigh sci-fi spectacle. Visual evidence: timecard, batch tattoo, worn gloves, queue for tools. Boundary: avoid generic factory crowd.', tags: ['batch_born', 'worker'] },
  { id: 'duplicate_pop_idol', name: '复制流行偶像', nameEn: 'Duplicate Pop Idol', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 4, risk: 'medium', def: '第一识别是可复制外貌和舞台人格的流行偶像。造型入口：舞台服、耳返编号、与宣传照完全一致的笑容、但眼神里有厌倦的偏差。母题：魅力被复制成商品库存。张力：不要普通偶像，重点是同款身体、档期替换和自我稀释。视觉证据：备用服装架、复制签名、后台镜阵、编号耳麦。边界：避免真实明星或品牌抄袭。', defEn: 'First read: a pop idol whose look and stage persona can be duplicated. Styling entry: stage outfit, in-ear monitor code, a smile identical to promo photos, but eyes drifting with fatigue. Motif: charm reproduced as inventory. Tension: not a generic idol; focus on same-model bodies, schedule replacement, and diluted selfhood. Visual evidence: backup costume rack, copied signatures, backstage mirror wall, coded headset. Boundary: avoid real celebrity or brand copy.', tags: ['duplicate', 'pop_idol'] },
  { id: 'clone_family_mother', name: '克隆家庭母亲', nameEn: 'Clone-Family Mother', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 4, risk: 'medium', def: '第一识别是照顾一组相同孩子、母职被复制技术逼到极限的母亲。造型入口：家居围裙、颜色标记、孩子编号照片、她能从细小习惯认出每一个。母题：家庭亲密对抗批量身体。张力：她不是普通母亲，爱必须通过微差辨认成立。视觉证据：不同发夹、餐盘编号、疲惫但准确的目光。边界：避免恐怖克隆妈妈或温情泛化。', defEn: 'First read: a mother caring for identical children, with motherhood pushed to the limit by cloning. Styling entry: home apron, color markers, numbered child photos, and ability to recognize each by tiny habits. Motif: family intimacy resisting batch bodies. Tension: not a generic mother; love exists through micro-difference recognition. Visual evidence: different hairclips, numbered plates, tired but precise gaze. Boundary: avoid horror clone mom or vague warmth.', tags: ['clone_family', 'mother'] },
  { id: 'backup_body_prince', name: '备用身体王子', nameEn: 'Backup-Body Prince', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 4, def: '第一识别是被培养为继承人备用身体的王子。造型入口：贵族制服、身体检查封签、和正主相似却缺少公开徽章的轮廓、被教导保持可替换的姿态。母题：血统继承变成库存管理。张力：他不是真正王子也不是普通克隆，核心是身份悬置。视觉证据：冷库钥匙、家徽缺位、体检表、练习过的礼仪。边界：避免童话王子或政治替身泛化。', defEn: 'First read: a prince cultivated as backup body for an heir. Styling entry: noble uniform, body-check seals, silhouette similar to the original but missing public emblems, and posture trained for replaceability. Motif: bloodline inheritance as inventory management. Tension: neither true prince nor generic clone; suspended identity is the core. Visual evidence: cold-storage key, absent crest, medical form, practiced etiquette. Boundary: avoid fairy-tale prince or generic political double.', tags: ['backup_body', 'prince'] },
  { id: 'identical_classroom_girl', name: '同脸教室女孩', nameEn: 'Identical-Classroom Girl', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 3, risk: 'medium', def: '第一识别是教室里许多同脸学生之一，却试图让老师记住自己。造型入口：校服、座位编号、课本边缘私写名字、发型只差一点点。母题：教育秩序放大了可替代性。张力：不要惊悚复制人，重点是日常中被认错的挫败。视觉证据：点名册、同款书包、偷偷改短的裙摆、期待回应的眼神。边界：避免普通校园群像。', defEn: 'First read: one of many identical-faced students in a classroom trying to be remembered. Styling entry: uniform, seat number, private name written on textbook edges, hairstyle differing only slightly. Motif: school order amplifying replaceability. Tension: not clone horror; focus on everyday frustration of being mistaken. Visual evidence: attendance list, same backpacks, secretly shortened hem, eyes waiting for response. Boundary: avoid generic school crowd.', tags: ['identical_classroom', 'girl'] },
  { id: 'replacement_child_subject', name: '替换儿童对象', nameEn: 'Replacement Child Subject', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 4, risk: 'medium', def: '第一识别是被制造出来填补失去孩子位置的替换对象。造型入口：不合时宜的新衣、旧家庭照片对照、名字牌被反复修改、努力模仿照片里的站姿。母题：复制身体被要求承担他人的亲密记忆。张力：保持非猎奇，重点是错位、讨好和无法成为原件。视觉证据：照片夹、尺码标签、手写名字、僵硬微笑。边界：避免恐怖小孩或温情治愈模板。', defEn: 'First read: a subject made to fill the place of a lost child. Styling entry: inappropriately new clothes, comparison with old family photos, repeatedly changed name tag, and trying to mimic posture in a picture. Motif: duplicate body forced to carry someone else intimacy memory. Tension: keep non-spectacular; focus on mismatch, appeasement, and inability to be the original. Visual evidence: photo folder, size labels, handwritten name, stiff smile. Boundary: avoid horror child or healing-family template.', tags: ['replacement_child', 'subject'] },
  { id: 'clone_rebellion_leader', name: '克隆叛乱领袖', nameEn: 'Clone Rebellion Leader', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 4, risk: 'medium', def: '第一识别是用同一张脸组织许多个体差异的克隆叛乱领袖。造型入口：改造制服、划掉批次号、临时旗帜、说话时让身后相似脸孔各自站开。母题：复制系统内部产生政治主体。张力：不要普通革命者，重点是她如何把“相同”变成集体力量。视觉证据：涂改编号、手势分队、不同伤疤、坚定侧脸。边界：避免克隆军团口号化。', defEn: 'First read: a clone rebellion leader organizing individual difference through the same face. Styling entry: altered uniform, crossed-out batch number, improvised flag, and arranging similar faces behind her into distinct positions. Motif: political subject emerging inside replication system. Tension: not a generic revolutionary; focus on turning sameness into collective force. Visual evidence: overwritten codes, squad gestures, different scars, firm profile. Boundary: avoid clone-army slogan image.', tags: ['clone_rebellion', 'leader'] },
  { id: 'serial_bride_project', name: '连续新娘计划', nameEn: 'Serial Bride Project', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 4, risk: 'high', def: '第一识别是同一套新娘身体被连续复制、用于不同联姻或仪式的项目个体。造型入口：白纱编号、试穿痕迹、相同婚戒尺寸、她把裙摆改出私人标记。母题：婚姻身份被批量生产。张力：不要普通新娘，重点是亲密制度、库存身体和反抗细节。视觉证据：婚纱架、批次标签、剪开的内衬、冷静眼神。边界：避免婚纱恐怖或恋物化。', defEn: 'First read: an individual from a project that serially copies the same bride body for alliances or rituals. Styling entry: numbered veil, fitting traces, identical ring size, and private marks altered into the hem. Motif: marital identity mass-produced. Tension: not a generic bride; focus on intimacy institution, inventory body, and small resistance. Visual evidence: gown rack, batch labels, cut lining, calm eyes. Boundary: avoid bridal horror or fetishization.', tags: ['serial_bride', 'project'] },
  { id: 'gene_copy_detective', name: '基因复制侦探', nameEn: 'Gene-Copy Detective', group: 'H. 克隆 / 复制 / 批量身体', groupEn: 'H. Clone / Duplicate / Batch Body', ontologyLevel: 3, def: '第一识别是靠识别基因复制痕迹办案的侦探，自己也可能是复制链的一环。造型入口：旧风衣、DNA报告、放大镜退化成采样棒、看见相似脸时停顿。母题：调查身份犯罪时反向怀疑自身。张力：不是普通侦探，重点是血样、档案和自我可疑。视觉证据：样本袋、复制谱系图、半遮脸、沉默凝视。边界：避免纯赛博黑客或硬汉侦探。', defEn: 'First read: a detective solving cases through gene-copy traces, possibly part of a copy chain himself. Styling entry: old coat, DNA reports, magnifier replaced by swabs, and pauses before similar faces. Motif: investigating identity crime while suspecting selfhood. Tension: not generic detective; focus on blood samples, files, and self-suspicion. Visual evidence: sample bags, copy lineage chart, half-hidden face, silent stare. Boundary: avoid pure cyber hacker or noir tough guy.', tags: ['gene_copy', 'detective'] },

  { id: 'fungal_saint_girl', name: '真菌圣女', nameEn: 'Fungal Saint Girl', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 5, risk: 'high', def: '第一识别是被群体视为圣女、身体却由真菌生态慢慢占领的年轻女性。造型入口：菌冠、白衣上的孢子粉、温柔合掌和皮肤下蔓延的菌丝。母题：神圣崇拜掩盖生态感染。张力：不要真正神迹化，重点是被供奉、被寄生和仍保持人形。视觉证据：祭台湿气、菌丝纹、低垂眼神、供品发霉。边界：避免普通花仙或宗教圣女。', defEn: 'First read: a young woman treated as a saint while fungal ecology slowly occupies her body. Styling entry: fungal crown, spore dust on white clothing, gentle clasped hands, and mycelium spreading under skin. Motif: sacred worship hiding ecological infection. Tension: avoid real miracle; focus on being worshipped, parasitized, and still human-shaped. Visual evidence: altar dampness, mycelium lines, lowered eyes, moldy offerings. Boundary: avoid flower fairy or religious saint.', tags: ['fungal_saint', 'girl'] },
  { id: 'moss_lung_child', name: '苔肺儿童', nameEn: 'Moss-Lung Child', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 4, risk: 'medium', def: '第一识别是肺部像苔藓生态一样需要潮湿环境的儿童。造型入口：小型加湿器、胸口苔色阴影、呼吸慢、衣领总带湿气。母题：呼吸变成微型生态维护。张力：保持非猎奇，重点是环境依赖和身体脆弱。视觉证据：雾气面罩、苔点、护理记录、安静坐姿。边界：避免恐怖儿童或普通哮喘病号。', defEn: 'First read: a child whose lungs function like moss ecology and need damp conditions. Styling entry: small humidifier, moss-colored chest shadow, slow breathing, and collar always carrying moisture. Motif: breathing as micro-ecology maintenance. Tension: keep non-spectacular; focus on environmental dependence and bodily fragility. Visual evidence: mist mask, moss spots, care record, quiet sitting posture. Boundary: avoid horror child or generic asthma patient.', tags: ['moss_lung', 'child'] },
  { id: 'flowering_skin_bride', name: '开花皮肤新娘', nameEn: 'Flowering-Skin Bride', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 5, risk: 'high', def: '第一识别是皮肤在婚礼前后开花、亲密仪式与生态感染缠在一起的新娘。造型入口：白纱下的小花芽、锁骨花粉、手套遮不住的花茎和不敢拥抱的姿态。母题：婚礼身体成为生长表面。张力：不要唯美花嫁化，花必须带来疼痛、过敏和被观看压力。视觉证据：花瓣掉落、皮肤红痕、婚戒、隔离花束。边界：避免普通花仙新娘。', defEn: 'First read: a bride whose skin flowers around the wedding, tying intimacy ritual to ecological infection. Styling entry: buds under veil, pollen at collarbone, stems escaping gloves, and posture afraid of embrace. Motif: bridal body becoming a growth surface. Tension: avoid pretty flower bride; flowers must bring pain, allergy, and pressure of being viewed. Visual evidence: fallen petals, red skin marks, wedding ring, isolated bouquet. Boundary: avoid generic flower fairy bride.', tags: ['flowering_skin', 'bride'] },
  { id: 'root_vein_farmer', name: '根脉农夫', nameEn: 'Root-Vein Farmer', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 4, def: '第一识别是血管与根系图案重叠、身体像土地一样被耕作经验改变的农夫。造型入口：泥土裤脚、手臂根脉纹、种袋、站在地里时像被地面牵住。母题：耕种者和作物生态互相渗透。张力：不要树人化，重点是劳动、土壤和身体慢性改变。视觉证据：泥下指甲、根状血管、工具磨痕、低头观察土壤。边界：避免普通农夫或植物怪。', defEn: 'First read: a farmer whose veins overlap root patterns, body altered by working land. Styling entry: muddy cuffs, root-vein lines on arms, seed bag, and a stance held by the ground. Motif: farmer and crop ecology seeping into each other. Tension: not a tree person; focus on labor, soil, and chronic bodily change. Visual evidence: dirt under nails, rootlike vessels, tool wear, head lowered to inspect soil. Boundary: avoid generic farmer or plant monster.', tags: ['root_vein', 'farmer'] },
  { id: 'spore_eye_teacher', name: '孢子眼教师', nameEn: 'Spore-Eye Teacher', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 4, risk: 'medium', def: '第一识别是眼部孢子让她看东西像通过粉尘层过滤的教师。造型入口：眼镜内侧雾粉、粉笔灰与孢子混合、课堂手势仍然稳定。母题：知识传递被生态感染轻微污染。张力：不是恐怖老师，重点是专业坚持和视力变化。视觉证据：擦眼镜布、孢子斑点、教案、学生保持距离。边界：避免普通霉菌怪。', defEn: 'First read: a teacher whose spore-filled eyes see through a dusty filter. Styling entry: powder inside glasses, chalk dust mixing with spores, and classroom gestures still steady. Motif: knowledge transmission lightly contaminated by ecology. Tension: not a horror teacher; focus on professional persistence and altered sight. Visual evidence: lens cloth, spore spots, lesson plan, students keeping distance. Boundary: avoid generic mold monster.', tags: ['spore_eye', 'teacher'] },
  { id: 'lichen_face_widow', name: '地衣脸寡妇', nameEn: 'Lichen-Face Widow', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 4, risk: 'medium', def: '第一识别是面部地衣斑与丧服共同形成缓慢哀悼感的寡妇。造型入口：黑纱、脸侧地衣纹、旧戒指、动作安静到像等时间覆盖自己。母题：悲伤像地衣一样缓慢附着。张力：不要鬼魅化，重点是时间、失去和生态表面。视觉证据：干湿交替斑、手帕、墓地泥痕、低声呼吸。边界：避免普通丧服或妖怪脸谱。', defEn: 'First read: a widow whose facial lichen patches and mourning clothes form slow grief. Styling entry: black veil, lichen patterns on one cheek, old ring, and movements quiet as if waiting for time to cover her. Motif: grief attaching slowly like lichen. Tension: avoid ghost coding; focus on time, loss, and ecological surface. Visual evidence: wet-dry patches, handkerchief, graveyard mud, low breathing. Boundary: avoid generic mourning dress or monster face paint.', tags: ['lichen_face', 'widow'] },
  { id: 'green_blood_worker', name: '绿血工人', nameEn: 'Green-Blood Worker', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 4, risk: 'medium', def: '第一识别是绿色血液让工伤、劳动和污染检测都变得异常的工人。造型入口：工装、绿色渗血贴、被同事避开的工具、他习惯把伤口藏起来。母题：身体液体改变了劳动身份。张力：不是奇幻血统，重点是现实工伤和被筛查的压力。视觉证据：创可贴绿痕、检测纸、旧手套、尴尬站位。边界：避免普通外星人。', defEn: 'First read: a worker whose green blood makes injury, labor, and contamination checks abnormal. Styling entry: workwear, green seepage bandage, tools avoided by coworkers, and habit of hiding wounds. Motif: body fluid altering labor identity. Tension: not fantasy lineage; focus on real workplace injury and screening pressure. Visual evidence: green-stained bandage, test strip, old gloves, awkward placement. Boundary: avoid generic alien.', tags: ['green_blood', 'worker'] },
  { id: 'tree_bark_patient', name: '树皮病人', nameEn: 'Tree-Bark Patient', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 4, risk: 'medium', def: '第一识别是皮肤局部木质化、像树皮一样开裂的病人。造型入口：手臂树皮纹、软垫绷带、保湿药膏、动作小心避免皮肤崩裂。母题：人体表面慢慢变成植物边界。张力：不要树人奇观，重点是护理、疼痛和仍然穿衣生活。视觉证据：裂纹、药膏光泽、医生标记、衣袖磨损。边界：避免普通树怪。', defEn: 'First read: a patient with local skin lignification cracking like bark. Styling entry: bark texture on arms, padded bandages, moisturizing ointment, and careful movement to prevent splitting. Motif: human surface slowly becoming plant boundary. Tension: not tree-person spectacle; focus on care, pain, and still wearing clothes to live. Visual evidence: cracks, ointment shine, doctor marks, sleeve abrasion. Boundary: avoid generic tree monster.', tags: ['tree_bark', 'patient'] },
  { id: 'seed_pod_pregnant_mother', name: '种荚孕母', nameEn: 'Seed-Pod Pregnant Mother', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 5, risk: 'high', def: '第一识别是怀孕身体与种荚生长结构重叠的母亲。造型入口：腹部种荚轮廓、护腹布、植物护理记录、既保护又害怕体内生长的手势。母题：孕育被生态系统重新定义。张力：保持庄重，不做猎奇或露骨呈现；重点是母职、未知生命和身体主权。视觉证据：种荚纹、产检单、湿润布料、低头守护。边界：避免怪胎恐怖或情色化。', defEn: 'First read: a mother whose pregnancy overlaps with seed-pod growth structure. Styling entry: pod contour at abdomen, protective belly cloth, plant-care records, and gestures both protecting and fearing inner growth. Motif: gestation redefined by ecology. Tension: keep solemn, not spectacular or explicit; focus on motherhood, unknown life, and bodily agency. Visual evidence: pod pattern, prenatal sheet, damp cloth, lowered protective gaze. Boundary: avoid freak horror or eroticization.', tags: ['seed_pod', 'pregnant_mother'] },
  { id: 'fungal_network_oracle', name: '真菌网络预言者', nameEn: 'Fungal-Network Oracle', group: 'I. 生态感染 / 真菌植物化', groupEn: 'I. Ecological Infection / Fungal Vegetalization', ontologyLevel: 5, risk: 'high', def: '第一识别是通过真菌网络感知远处生态变化的预言者。造型入口：脚踝或手指接触菌丝地面、闭眼倾听、衣摆沾满孢子、说话像转述地下信息。母题：预言来自生态连接而不是神灵。张力：不要神秘万能，重点是连接代价、身体疲惫和信息延迟。视觉证据：菌丝地图、湿土、耳边孢粉、颤抖手指。边界：避免普通先知。', defEn: 'First read: an oracle sensing distant ecological change through fungal network. Styling entry: ankles or fingers touching mycelium ground, closed-eye listening, spore-covered hems, and speech like relaying underground information. Motif: prophecy from ecological connection, not deity. Tension: not all-powerful mystic; focus on connection cost, fatigue, and information delay. Visual evidence: mycelium map, wet soil, spore dust near ear, trembling fingers. Boundary: avoid generic prophet.', tags: ['fungal_network', 'oracle'] },

  { id: 'black_market_organ_girl', name: '黑市器官女孩', nameEn: 'Black-Market Organ Girl', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 3, risk: 'high', def: '第一识别是身体被黑市器官交易标价过的年轻女性。造型入口：便宜外套、体检标签、遮住腹侧疤痕的手、眼神知道自己被当成库存。母题：身体价值被拆成零件价格。张力：避免猎奇受害者，重点是警觉、交易痕迹和仍想保留尊严。视觉证据：账单、手术线、号码贴、紧握证件。边界：避免普通贫困少女或血腥器官展示。', defEn: 'First read: a young woman whose body has been priced by black-market organ trade. Styling entry: cheap coat, exam labels, a hand covering side-abdominal scars, and eyes knowing she is treated as inventory. Motif: body value split into part prices. Tension: avoid spectacle victimhood; focus on alertness, trade traces, and remaining dignity. Visual evidence: bills, surgical lines, number stickers, clenched ID. Boundary: avoid generic poor girl or bloody organ display.', tags: ['black_market_organ', 'girl'] },
  { id: 'illegal_clinic_assistant', name: '非法诊所助手', nameEn: 'Illegal Clinic Assistant', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 2, risk: 'high', def: '第一识别是在非法诊所里做助手、熟悉灰色医疗流程的人。造型入口：不合身白袍、塑料手套、现金账本、清洗过度的手和随时准备关灯的警觉。母题：医疗技术从制度边缘继续运转。张力：他不是邪恶医生，重点是低端专业性、恐惧和利益夹缝。视觉证据：旧手术灯、假药瓶、门帘、染色毛巾。边界：避免普通护士或黑帮小弟。', defEn: 'First read: an assistant inside an illegal clinic, fluent in gray medical procedure. Styling entry: ill-fitting white coat, plastic gloves, cash ledger, overwashed hands, and alertness ready to turn off lights. Motif: medical technique still operating at institutional margins. Tension: not an evil doctor; focus on low-end professionalism, fear, and compromised incentives. Visual evidence: old surgical lamp, fake medicine bottles, door curtain, stained towels. Boundary: avoid generic nurse or gangster henchman.', tags: ['illegal_clinic', 'assistant'] },
  { id: 'body_auction_model', name: '身体拍卖模特', nameEn: 'Body-Auction Model', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 3, risk: 'high', def: '第一识别是在身体拍卖场展示“可用性”的模特。造型入口：简洁展示服、测量线、匿名号码牌、职业姿态下面压着厌恶。母题：时装展示语法被身体交易挪用。张力：不要性感化，重点是冷酷流程、身体指标和被观看的羞耻。视觉证据：量尺、拍卖牌、医学灯、僵硬微笑。边界：避免普通走秀或露骨交易。', defEn: 'First read: a model displaying bodily "availability" at a body auction. Styling entry: minimal presentation outfit, measurement lines, anonymous number plate, and disgust held under professional posture. Motif: fashion display grammar repurposed for body trade. Tension: avoid sexualization; focus on cold procedure, body metrics, and shame of being viewed. Visual evidence: measuring tape, auction paddle, medical light, stiff smile. Boundary: avoid normal runway or explicit transaction.', tags: ['body_auction', 'model'] },
  { id: 'organ_debt_worker', name: '器官债工人', nameEn: 'Organ-Debt Worker', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 2, risk: 'high', def: '第一识别是用未来器官偿还债务的工人。造型入口：工装、债务腕带、腹侧合同疤、干活时下意识护住已抵押部位。母题：劳动债务直接写进身体。张力：现实残酷要压过科幻，重点是合同、劳作和不可见恐惧。视觉证据：欠条、体检日期、工具箱、手遮伤口。边界：避免普通负债工人。', defEn: 'First read: a worker repaying debt with future organs. Styling entry: workwear, debt wristband, contract scars at side abdomen, and protecting the pledged body part while working. Motif: labor debt written directly into the body. Tension: realistic cruelty over sci-fi spectacle; focus on contract, work, and invisible fear. Visual evidence: IOU note, exam date, toolbox, hand over wound. Boundary: avoid generic indebted worker.', tags: ['organ_debt', 'worker'] },
  { id: 'gene_tailor_doctor', name: '基因裁缝医生', nameEn: 'Gene-Tailor Doctor', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 4, risk: 'medium', def: '第一识别是像裁缝修改衣服一样修改人体基因的医生。造型入口：量体尺与采样针并列、白袍袖口有线迹、对身体轮廓的审美判断过于冷静。母题：医疗、设计和阶层需求合谋。张力：他不是疯狂科学家，危险来自温和专业和客户化身体。视觉证据：基因样布、剪刀、冷藏样本、试衣镜。边界：避免普通整形医生。', defEn: 'First read: a doctor altering genes like a tailor alters clothing. Styling entry: measuring tape beside sampling needle, stitch marks at white-coat cuffs, and overly calm aesthetic judgment of body outline. Motif: medicine, design, and class desire conspiring. Tension: not mad scientist; danger comes from gentle professionalism and customized bodies. Visual evidence: gene swatches, scissors, chilled samples, fitting mirror. Boundary: avoid generic plastic surgeon.', tags: ['gene_tailor', 'doctor'] },
  { id: 'surgery_cult_patient', name: '手术邪教病人', nameEn: 'Surgery-Cult Patient', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 4, risk: 'high', def: '第一识别是把反复手术当成净化仪式的患者。造型入口：病号服叠着仪式披布、整齐手术疤、崇敬医生的眼神、身体像等待下一次切开。母题：医学流程被信仰化。张力：不要真实宗教攻击，重点是手术、服从和被治疗语言驯化。视觉证据：术前编号、纱布、仪式符号、平静过头的表情。边界：避免血腥邪典。', defEn: 'First read: a patient treating repeated surgery as purification ritual. Styling entry: patient gown layered with ritual cloth, neat surgical scars, worshipful gaze toward doctors, and a body waiting to be opened again. Motif: medical procedure turned into belief. Tension: avoid attacking real religion; focus on surgery, obedience, and domestication by treatment language. Visual evidence: pre-op number, gauze, ritual signs, too-calm expression. Boundary: avoid gore cult image.', tags: ['surgery_cult', 'patient'] },
  { id: 'prosthetic_flesh_broker', name: '义肉掮客', nameEn: 'Prosthetic-Flesh Broker', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 4, risk: 'high', def: '第一识别是买卖培养肉体部件和替换组织的掮客。造型入口：深色外套、冷藏箱、样本目录、戴手套翻看肉质色卡的镇定。母题：血肉成为可议价商品。张力：他不是黑帮商人，危险来自礼貌、专业和库存化语言。视觉证据：温控箱、组织编号、报价单、无菌手套。边界：避免普通器官贩子或血腥摊位。', defEn: 'First read: a broker trading cultured flesh parts and replacement tissues. Styling entry: dark coat, refrigerated case, sample catalogue, and calm gloved browsing through flesh color swatches. Motif: flesh becomes negotiable commodity. Tension: not a gangster merchant; danger comes from politeness, professionalism, and inventory language. Visual evidence: temperature case, tissue codes, price sheet, sterile gloves. Boundary: avoid generic organ trafficker or bloody stall.', tags: ['prosthetic_flesh', 'broker'] },
  { id: 'medical_waste_orphan', name: '医疗废料孤儿', nameEn: 'Medical-Waste Orphan', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 3, risk: 'medium', def: '第一识别是在医疗废料和丢弃样本边缘长大的孤儿。造型入口：过大的防护手套、药瓶玩具、旧毯子、知道哪些箱子不能碰的成熟眼神。母题：被丢弃的医疗系统残片变成童年环境。张力：保持非猎奇，重点是求生知识和污染边界。视觉证据：黄色废料箱、破标签、消毒味、抱紧小包。边界：避免卖惨孤儿或恐怖儿童。', defEn: 'First read: an orphan raised near medical waste and discarded samples. Styling entry: oversized protective gloves, medicine-bottle toys, old blanket, and mature eyes knowing which boxes not to touch. Motif: discarded medical-system fragments becoming childhood environment. Tension: keep non-spectacular; focus on survival knowledge and contamination boundaries. Visual evidence: yellow waste bin, torn labels, disinfectant smell, small bag hugged tight. Boundary: avoid pity orphan or horror child.', tags: ['medical_waste', 'orphan'] },
  { id: 'embryo_smuggler', name: '胚胎走私者', nameEn: 'Embryo Smuggler', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 4, risk: 'high', def: '第一识别是携带冷藏胚胎穿过边境、把生命可能性当货物保护的走私者。造型入口：温控腰包、假旅行证件、手不离保温箱、眼神同时警惕海关和温度读数。母题：生命起点被物流化。张力：他不是普通走私犯，货物的脆弱性决定姿态。视觉证据：温度贴、伪装箱、汗水、路线票据。边界：避免犯罪片套路。', defEn: 'First read: a smuggler carrying refrigerated embryos across borders, protecting life possibility as cargo. Styling entry: temperature-control waist pack, fake travel documents, hand never leaving the case, and eyes tracking customs and temperature at once. Motif: the beginning of life turned into logistics. Tension: not a generic smuggler; cargo fragility dictates posture. Visual evidence: temperature sticker, disguised case, sweat, route tickets. Boundary: avoid crime-movie cliché.', tags: ['embryo', 'smuggler'] },
  { id: 'immortality_trial_billionaire', name: '永生试验富豪', nameEn: 'Immortality-Trial Billionaire', group: 'J. 禁忌医学 / 身体交易', groupEn: 'J. Forbidden Medicine / Body Trade', ontologyLevel: 4, risk: 'medium', def: '第一识别是用财富购买永生试验、身体被高端医疗拆成项目的富豪。造型入口：定制病房、西装外套披在病号服上、年轻化局部与衰老手部并置、对死亡极端不耐烦。母题：阶层权力试图收购时间。张力：不要超自然不死，重点是医疗豪华、身体焦虑和冷酷资源占用。视觉证据：私人医生、冷藏针剂、资产文件、镜前检查。边界：避免普通老富豪或吸血鬼。', defEn: 'First read: a billionaire buying immortality trials, body split into high-end medical projects. Styling entry: custom patient suite, suit jacket over hospital wear, rejuvenated areas beside aged hands, and extreme impatience with death. Motif: class power trying to purchase time. Tension: not supernatural immortality; focus on medical luxury, body anxiety, and cold resource capture. Visual evidence: private doctor, chilled injections, asset documents, mirror inspection. Boundary: avoid generic old tycoon or vampire.', tags: ['immortality_trial', 'billionaire'] },
];

export const CD_PERSONA_INFECTED_EXPERIMENT: PersonaTerm[] = seeds.map(ip);
